import{n as e,t}from"./listening-catalog-contract-CcfoU0P0.js";var n=[[`female_1`,`male_1`],[`male_2`,`female_2`],[`female_3`,`male_3`],[`male_1`,`female_3`],[`female_2`,`male_2`]];function r({slug:e,title:t,topic:n,cefr:r,voices:i,dialogue:a,questions:o}){let s=`listening-pilot-v1.interview.${e}`;return{id:s,revision:1,type:`interview`,title:t,topic:n,cefr:r,provenance:`original`,audio:{path:`/audio/listening/listening-pilot-v1/interview/${e}-r1.mp3`},script:a.map((e,t)=>({role:t%2==0?`interviewer`:`guest`,voiceSlot:i[t%2],text:e})),task:{questions:o.map((e,t)=>({id:`${s}.q${t+1}`,...e}))}}}var i=[r({slug:`urban-beekeeping`,title:`Bees above the city`,topic:`environment`,cefr:`B1`,voices:n[0],dialogue:[`Today we are meeting Daniel, who keeps bees on the roof of a city hotel. Daniel, how did you begin?`,`I joined a weekend course after my neighbour showed me a hive. The hotel manager later offered me roof space because the building has a large garden below it.`,`Some people imagine that country bees are always healthier. What have you observed in the city?`,`City parks provide flowers from early spring until autumn, so our bees find food for longer. Traffic is a concern, though, and we send honey to a laboratory twice a year.`,`Do hotel guests ever visit the hives, and what safety rules do you use?`,`We run small tours on Wednesday mornings. Visitors wear protective jackets and stand behind a painted line; anyone with a serious bee allergy must watch through the indoor window.`,`What happens to the honey, and what would you like to change next?`,`The kitchen uses most of it in breakfast dishes, while a few jars are sold to support a local tree-planting group. Next year I hope to add a camera so schools can observe the hive online.`],questions:[{prompt:`What first encouraged Daniel to learn about beekeeping?`,options:[`A hotel advertisement`,`His neighbour’s hive`,`A school science lesson`,`A family business`],answer:1,quote:`my neighbour showed me a hive`,explanationRu:`Именно сосед показал Дэниелу улей, после чего он записался на курс.`},{prompt:`Why could Daniel place hives at the hotel?`,options:[`The roof was beside a garden`,`The guests requested honey`,`The city paid for the equipment`,`The kitchen had unused rooms`],answer:0,quote:`the building has a large garden below it`,explanationRu:`Менеджер предложил крышу из-за большого сада под зданием.`},{prompt:`What advantage do city bees have, according to Daniel?`,options:[`They make sweeter honey`,`They avoid all diseases`,`They can find flowers for more months`,`They need fewer inspections`],answer:2,quote:`provide flowers from early spring until autumn`,explanationRu:`Городские парки дают цветы с ранней весны до осени, то есть дольше.`},{prompt:`How often is the honey tested?`,options:[`Every month`,`Twice a year`,`Once a year`,`Every Wednesday`],answer:1,quote:`we send honey to a laboratory twice a year`,explanationRu:`Дэниел прямо называет периодичность: дважды в год.`},{prompt:`When can guests take a hive tour?`,options:[`Wednesday mornings`,`Friday evenings`,`Saturday afternoons`,`Sunday mornings`],answer:0,quote:`small tours on Wednesday mornings`,explanationRu:`Экскурсии проходят по средам утром.`},{prompt:`What must visitors with a serious allergy do?`,options:[`Bring their own medicine`,`Wear two protective jackets`,`Stay behind the hotel`,`Observe from indoors`],answer:3,quote:`must watch through the indoor window`,explanationRu:`При серьёзной аллергии разрешено наблюдать только из помещения через окно.`},{prompt:`What is Daniel planning to add next year?`,options:[`A larger kitchen`,`An online hive camera`,`A second laboratory`,`A honey shop`],answer:1,quote:`add a camera so schools can observe the hive online`,explanationRu:`Следующий план — камера для онлайн-наблюдения школьниками.`}]}),r({slug:`youth-orchestra`,title:`A youth orchestra conductor`,topic:`music`,cefr:`B2`,voices:n[1],dialogue:[`Our guest is conductor Maya Chen, whose youth orchestra recently toured three towns. Maya, did you always intend to conduct?`,`Not at all. I trained as a violinist, but during college a lecturer asked me to lead a rehearsal when she was ill. I discovered that helping sixty people shape one musical idea was more exciting than performing my own part.`,`How do auditions work for teenagers who want to join your orchestra?`,`They play one prepared piece and a short passage they have never seen. Technical accuracy matters, but we also notice whether applicants listen and adjust when another musician joins them.`,`Your latest programme mixed classical and newly written music. Was that a difficult choice?`,`The players selected the contemporary piece themselves after hearing three composers present their ideas. At first some parents expected only famous works, but the new piece received the longest applause on tour.`,`What did the tour teach you, and what is the orchestra doing next?`,`Travelling showed us that a quiet rehearsal room had hidden our balance problems; unfamiliar halls forced everyone to listen more carefully. Next term we will work with a deaf theatre group and explore how movement and light can communicate rhythm.`],questions:[{prompt:`What instrument did Maya originally study?`,options:[`The piano`,`The violin`,`The flute`,`The cello`],answer:1,quote:`I trained as a violinist`,explanationRu:`До дирижирования Майя обучалась игре на скрипке.`},{prompt:`Why did Maya first lead a rehearsal?`,options:[`A lecturer was unwell`,`She won a competition`,`The conductor missed a train`,`Students elected her`],answer:0,quote:`a lecturer asked me to lead a rehearsal when she was ill`,explanationRu:`Первую репетицию она провела вместо заболевшей преподавательницы.`},{prompt:`What do applicants receive without preparation?`,options:[`A complete symphony`,`A list of questions`,`A short musical passage`,`A conducting task`],answer:2,quote:`a short passage they have never seen`,explanationRu:`На прослушивании дают короткий незнакомый отрывок.`},{prompt:`Which quality does the orchestra assess besides technical accuracy?`,options:[`Ability to compose`,`Willingness to travel`,`Knowledge of music history`,`Response to other players`],answer:3,quote:`whether applicants listen and adjust when another musician joins them`,explanationRu:`Проверяется умение слушать партнёра и подстраиваться к нему.`},{prompt:`Who chose the contemporary work for the programme?`,options:[`The parents`,`The musicians`,`The tour managers`,`The audience`],answer:1,quote:`The players selected the contemporary piece themselves`,explanationRu:`Современную пьесу выбрали сами участники оркестра.`},{prompt:`What weakness became clear during the tour?`,options:[`Poor balance between instruments`,`Insufficient ticket sales`,`A lack of new uniforms`,`Weak stage lighting`],answer:0,quote:`a quiet rehearsal room had hidden our balance problems`,explanationRu:`Новые залы выявили проблемы баланса, скрытые привычной репетиционной комнатой.`},{prompt:`Who will collaborate with the orchestra next term?`,options:[`A dance school`,`Three composers`,`A deaf theatre group`,`A parents’ choir`],answer:2,quote:`work with a deaf theatre group`,explanationRu:`Следующее сотрудничество запланировано с театральной группой глухих.`}]}),r({slug:`repair-cafe`,title:`Giving broken things another life`,topic:`technology`,cefr:`B1`,voices:n[2],dialogue:[`Priya organises a monthly repair café where volunteers fix household objects. What gave you the idea?`,`My electric lamp stopped working, and a retired engineer at our library repaired it in ten minutes. I realised many useful objects are thrown away because people lack one small skill or tool.`,`What can visitors bring, and do they have to pay for repairs?`,`We accept clothes, small electrical devices and simple wooden furniture, but not microwaves because they can store dangerous electrical charges. Entry is free; visitors only pay if a replacement part is needed.`,`Do volunteers simply take the object away and return it fixed?`,`No, the owner sits beside the volunteer and follows each step. Our purpose is education as much as repair, so even children can learn safe tasks such as sewing on a button.`,`How successful has the project been, and what is your next priority?`,`Last month we repaired thirty-eight of fifty objects. We could not fix the rest because parts were unavailable, not because we ran out of time. Now we need volunteers who understand modern phones and tablets.`],questions:[{prompt:`Which object led Priya to create the repair café?`,options:[`A wooden chair`,`A mobile phone`,`An electric lamp`,`A microwave`],answer:2,quote:`My electric lamp stopped working`,explanationRu:`Идея возникла после поломки электрической лампы.`},{prompt:`Why are many objects discarded, in Priya’s view?`,options:[`Repairs are always illegal`,`People lack a minor skill or tool`,`New products are cheaper`,`Libraries refuse to help`],answer:1,quote:`people lack one small skill or tool`,explanationRu:`Причиной она считает нехватку небольшого навыка или инструмента.`},{prompt:`Which item does the café refuse to repair?`,options:[`Clothes`,`Wooden furniture`,`Small electrical devices`,`Microwaves`],answer:3,quote:`not microwaves because they can store dangerous electrical charges`,explanationRu:`Микроволновые печи не принимают из-за опасного заряда.`},{prompt:`When does a visitor need to pay?`,options:[`When a new part is required`,`Whenever a volunteer helps`,`When the repair takes over an hour`,`When a child attends`],answer:0,quote:`visitors only pay if a replacement part is needed`,explanationRu:`Оплата нужна только за необходимую запасную деталь.`},{prompt:`What is expected of an object’s owner during a repair?`,options:[`To leave the building`,`To observe and learn`,`To bring a professional`,`To sign a sales contract`],answer:1,quote:`the owner sits beside the volunteer and follows each step`,explanationRu:`Владелец остаётся рядом и следит за всеми этапами, чтобы учиться.`},{prompt:`Why were twelve objects not repaired last month?`,options:[`The café closed early`,`They were all microwaves`,`Replacement parts could not be found`,`There were no sewing tools`],answer:2,quote:`because parts were unavailable, not because we ran out of time`,explanationRu:`Двенадцать предметов не починили из-за отсутствия деталей.`},{prompt:`What expertise does the café currently need?`,options:[`Phone and tablet repair`,`Furniture design`,`Library management`,`Children’s teaching`],answer:0,quote:`volunteers who understand modern phones and tablets`,explanationRu:`Сейчас особенно нужны специалисты по современным телефонам и планшетам.`}]}),r({slug:`marine-biologist`,title:`Studying life in a seagrass meadow`,topic:`science`,cefr:`B2`,voices:n[3],dialogue:[`Dr Lewis studies seagrass meadows along the coast. Why focus on a plant that many swimmers hardly notice?`,`Seagrass creates a nursery for young fish and stores carbon in the mud beneath it. I became interested after a storm removed a meadow near my childhood beach and the water stayed cloudy for months.`,`How does your team collect information without damaging this habitat?`,`Divers photograph fixed squares on the seabed instead of pulling up plants. We also use small sound recorders because the clicks and calls of animals reveal activity that cameras miss at night.`,`Local boat owners were worried about your proposed protected zone. How did you respond?`,`We moved two boundary markers after fishers showed us their safest route into the harbour. The protected area became slightly smaller, but cooperation means anchors are now kept out of its most fragile section.`,`What result has surprised you most, and what will happen next?`,`After only eighteen months, young seahorses returned to a restored meadow, much earlier than our three-year estimate. We will now compare whether hand-planted shoots or naturally spreading patches survive winter storms better.`],questions:[{prompt:`What environmental service does seagrass provide?`,options:[`It warms coastal water`,`It stores carbon in seabed mud`,`It prevents every storm`,`It removes salt from water`],answer:1,quote:`stores carbon in the mud beneath it`,explanationRu:`Морская трава накапливает углерод в иле под растениями.`},{prompt:`What event first attracted Dr Lewis to the subject?`,options:[`A storm destroyed a local meadow`,`A diver found a new fish`,`A school opened a laboratory`,`A boat damaged his camera`],answer:0,quote:`a storm removed a meadow near my childhood beach`,explanationRu:`Интерес возник после уничтожения знакомого луга штормом.`},{prompt:`Why does the team use underwater sound recorders?`,options:[`To guide boats into harbour`,`To measure water temperature`,`To identify activity cameras miss in darkness`,`To frighten fish away`],answer:2,quote:`reveal activity that cameras miss at night`,explanationRu:`Звук помогает фиксировать ночную активность, которую не видят камеры.`},{prompt:`Why were two protected-zone markers moved?`,options:[`Tourists complained about the view`,`Fishers indicated a safe harbour route`,`The seagrass moved offshore`,`The cameras required deeper water`],answer:1,quote:`fishers showed us their safest route into the harbour`,explanationRu:`Границы изменили с учётом безопасного маршрута рыбаков в гавань.`},{prompt:`What benefit resulted from cooperation with boat owners?`,options:[`All fishing was banned`,`A new harbour was built`,`Anchors avoid the most delicate area`,`The protected zone doubled`],answer:2,quote:`anchors are now kept out of its most fragile section`,explanationRu:`Сотрудничество позволило убрать якоря из самой уязвимой части.`},{prompt:`What surprised the researchers about the seahorses?`,options:[`They returned sooner than predicted`,`They survived without seagrass`,`They arrived during a storm`,`They were larger than adults`],answer:0,quote:`returned to a restored meadow, much earlier than our three-year estimate`,explanationRu:`Морские коньки вернулись значительно раньше трёхлетнего прогноза.`},{prompt:`What will the next study compare?`,options:[`Two kinds of underwater camera`,`Winter and summer tourism`,`Different harbour entrances`,`Planted and naturally spreading seagrass`],answer:3,quote:`compare whether hand-planted shoots or naturally spreading patches survive winter storms better`,explanationRu:`Будут сравнивать вручную высаженные и естественно разросшиеся участки.`}]}),r({slug:`student-newspaper`,title:`Editing a student newspaper`,topic:`media`,cefr:`B1`,voices:n[4],dialogue:[`Sofia edits her school newspaper. Was journalism already your main interest when you joined?`,`I actually joined because I wanted to improve my photography. In my second term, the editor asked me to rewrite a confusing report, and I found that making facts clear was even more satisfying.`,`How does your team decide which stories deserve space in the printed edition?`,`We publish short announcements online, while print space goes to investigations and interviews that readers may keep. Every proposal must explain why the subject affects students rather than simply being popular.`,`Have you ever published a story that caused disagreement?`,`Our article about expensive cafeteria meals upset the catering company. We showed them the price survey before publication and printed their full response, but we did not remove our comparison with nearby schools.`,`What have you learned as editor, and what change are you planning?`,`I used to correct every sentence myself, which made the team dependent on me. Now section editors give the first feedback. Next month we are introducing an audio edition for students who find long printed texts difficult.`],questions:[{prompt:`Why did Sofia originally join the newspaper?`,options:[`To practise photography`,`To become an editor`,`To investigate school meals`,`To record audio`],answer:0,quote:`I wanted to improve my photography`,explanationRu:`Первоначальной целью Софии было улучшить навыки фотографии.`},{prompt:`What made Sofia more interested in writing?`,options:[`Interviewing a famous actor`,`Rewriting an unclear report`,`Winning a school prize`,`Publishing a photograph`],answer:1,quote:`the editor asked me to rewrite a confusing report`,explanationRu:`Интерес к тексту появился после редактирования непонятного отчёта.`},{prompt:`Which material is usually reserved for print?`,options:[`Short daily notices`,`Lunch menus`,`Investigations and interviews`,`Sports scores only`],answer:2,quote:`print space goes to investigations and interviews`,explanationRu:`Печатные полосы отдают расследованиям и интервью.`},{prompt:`What must every proposed story demonstrate?`,options:[`That it will attract advertisers`,`That it concerns students`,`That it includes photographs`,`That teachers approve it`],answer:1,quote:`explain why the subject affects students`,explanationRu:`Каждая тема должна показать своё влияние на учеников.`},{prompt:`How did the team treat the catering company fairly?`,options:[`It cancelled the article`,`It changed all the prices`,`It hid the school comparison`,`It shared the survey and printed the response`],answer:3,quote:`showed them the price survey before publication and printed their full response`,explanationRu:`Компании заранее показали данные и полностью опубликовали её ответ.`},{prompt:`Why did Sofia stop correcting every sentence herself?`,options:[`It made colleagues too dependent on her`,`She disliked grammar`,`The newspaper became shorter`,`Teachers banned editing`],answer:0,quote:`which made the team dependent on me`,explanationRu:`Такой подход создавал зависимость всей команды от одного редактора.`},{prompt:`What new format will the newspaper offer?`,options:[`A daily television show`,`An audio edition`,`A paid mobile game`,`A handwritten edition`],answer:1,quote:`introducing an audio edition`,explanationRu:`Запланирована аудиоверсия газеты.`}]}),r({slug:`wheelchair-basketball`,title:`Competing in wheelchair basketball`,topic:`sport`,cefr:`B2`,voices:n[0],dialogue:[`Marcus plays wheelchair basketball for a regional team. What surprised you when you first tried the sport?`,`I expected my ordinary wheelchair to be suitable, but sports chairs have angled wheels and turn far faster. For the first month, controlling the chair exhausted me more than throwing the ball.`,`How is a team organised when players have different levels of mobility?`,`Each athlete receives a classification number, and the five players on court must stay below a combined limit. It is not a judgement of talent; it keeps the physical balance fair while allowing varied roles.`,`What has been the biggest challenge in travelling to matches?`,`Venues are usually accessible, but rail companies sometimes separate players from their sports chairs. After one chair arrived a day late, our club bought protective tracking cases rather than abandoning train travel.`,`You recently started coaching younger players. Has that changed your own game?`,`Definitely. Explaining how to create space made me notice that I moved too early in defence. The juniors train on Saturdays, and next season I hope two of them will join our development squad.`],questions:[{prompt:`What did Marcus initially misunderstand about the equipment?`,options:[`He thought a normal wheelchair would work`,`He expected the ball to be smaller`,`He believed helmets were required`,`He assumed chairs had brakes`],answer:0,quote:`I expected my ordinary wheelchair to be suitable`,explanationRu:`Маркус ошибочно считал обычную коляску подходящей для игры.`},{prompt:`What tired Marcus most during his first month?`,options:[`Travelling by train`,`Practising free throws`,`Steering the sports chair`,`Coaching children`],answer:2,quote:`controlling the chair exhausted me more than throwing the ball`,explanationRu:`Больше бросков его утомляло управление спортивной коляской.`},{prompt:`Why are classification numbers used?`,options:[`To select team captains`,`To maintain fair physical balance`,`To measure shooting talent`,`To decide ticket prices`],answer:1,quote:`keeps the physical balance fair`,explanationRu:`Классификация нужна для справедливого физического баланса состава.`},{prompt:`What transport problem has the team experienced?`,options:[`Venues refused entry`,`Tickets were sold twice`,`Trains had no players’ seats`,`Sports chairs travelled separately and one was late`],answer:3,quote:`rail companies sometimes separate players from their sports chairs. After one chair arrived a day late`,explanationRu:`Одна спортивная коляска, перевозимая отдельно, опоздала на сутки.`},{prompt:`How did the club respond to the delayed chair?`,options:[`It stopped using trains`,`It bought tracked protective cases`,`It rented a private bus`,`It cancelled away matches`],answer:1,quote:`bought protective tracking cases rather than abandoning train travel`,explanationRu:`Клуб купил защитные кейсы с отслеживанием и сохранил поездки на поезде.`},{prompt:`What did coaching reveal about Marcus’s defending?`,options:[`He moved too soon`,`He watched the ball too little`,`He never created space`,`He used the wrong chair`],answer:0,quote:`I moved too early in defence`,explanationRu:`Объясняя игру, Маркус заметил, что слишком рано движется в защите.`},{prompt:`What does Marcus hope will happen next season?`,options:[`The junior sessions will move to Friday`,`The club will buy five trains`,`Two juniors will enter the development squad`,`Classification will be removed`],answer:2,quote:`two of them will join our development squad`,explanationRu:`Он надеется, что двое юниоров попадут в команду развития.`}]}),r({slug:`heritage-railway`,title:`Volunteering on a heritage railway`,topic:`travel`,cefr:`B1`,voices:n[1],dialogue:[`Ella volunteers on a heritage railway. What did you do on your first day?`,`I expected to sell tickets, but the station master gave me a paintbrush. We restored old platform signs, and an experienced volunteer showed me how to copy the original lettering.`,`What roles can young volunteers take as they gain experience?`,`At sixteen they can help passengers and work in the café. Safety training is required before anyone enters the workshop, and only adults may work directly on the steam engine.`,`Where does the railway get the money for restoration?`,`Ticket sales cover normal running costs. For major repairs we apply for heritage grants and run special evening journeys; last winter one such journey paid for new carriage windows.`,`Why do you continue volunteering, and what project comes next?`,`I enjoy hearing former railway workers describe details that books leave out. This autumn we will record their memories, then add short listening points around the station instead of creating another printed exhibition.`],questions:[{prompt:`What task did Ella receive on her first day?`,options:[`Driving a train`,`Painting platform signs`,`Selling café food`,`Repairing an engine`],answer:1,quote:`We restored old platform signs`,explanationRu:`Первой работой Эллы было восстановление старых табличек на платформе.`},{prompt:`What did an experienced volunteer teach Ella?`,options:[`How to copy historic lettering`,`How to inspect tickets`,`How to light a steam engine`,`How to make station announcements`],answer:0,quote:`showed me how to copy the original lettering`,explanationRu:`Её научили воспроизводить оригинальный стиль букв.`},{prompt:`What must happen before a volunteer enters the workshop?`,options:[`They must turn eighteen`,`They must buy a uniform`,`They must complete safety training`,`They must work in the café`],answer:2,quote:`Safety training is required before anyone enters the workshop`,explanationRu:`Для входа в мастерскую обязательно обучение безопасности.`},{prompt:`Who may work directly on the steam engine?`,options:[`Only adults`,`All café workers`,`Passengers over sixteen`,`Grant providers`],answer:0,quote:`only adults may work directly on the steam engine`,explanationRu:`Непосредственная работа с паровозом разрешена только взрослым.`},{prompt:`What do ticket sales pay for?`,options:[`New carriage windows only`,`Recorded interviews`,`Ordinary operating costs`,`All major restoration`],answer:2,quote:`Ticket sales cover normal running costs`,explanationRu:`Билеты покрывают обычные эксплуатационные расходы.`},{prompt:`How were new carriage windows funded?`,options:[`By a school donation`,`By an evening journey`,`By café profits`,`By a television company`],answer:1,quote:`one such journey paid for new carriage windows`,explanationRu:`Новые окна оплатил доход от специальной вечерней поездки.`},{prompt:`How will former workers’ memories be presented?`,options:[`In a new printed exhibition`,`In a weekly newspaper`,`On the train tickets`,`At listening points around the station`],answer:3,quote:`add short listening points around the station`,explanationRu:`Записи воспоминаний будут доступны в аудиоточках по станции.`}]}),r({slug:`sleep-research`,title:`Testing better sleep habits`,topic:`health`,cefr:`B2`,voices:n[2],dialogue:[`Professor Hall studies teenage sleep. Why do school-age teenagers often fall asleep later than adults expect?`,`Their body clock naturally shifts during adolescence, so feeling awake late at night is not simply poor discipline. Bright screens can delay sleep further, but biology starts the change.`,`You recently tested a later school start. How was the study organised?`,`One school moved its first lesson from eight to nine for six weeks, while a similar school kept its usual timetable. Students wore movement sensors; we did not rely only on diaries.`,`What changed during those six weeks?`,`The later-start group slept an average of thirty-four minutes more and reported better concentration in first lessons. Their total test scores did not rise, although late arrivals became less common.`,`Does this mean every school should immediately begin at nine?`,`No. Our sample was small, and winter darkness may have influenced the result. We are repeating the study in spring and will also measure whether afternoon sports attendance changes.`],questions:[{prompt:`What is the main initial reason teenagers fall asleep later?`,options:[`A biological shift in the body clock`,`Too much afternoon sport`,`Strict school discipline`,`Winter examinations`],answer:0,quote:`Their body clock naturally shifts during adolescence`,explanationRu:`Первичная причина — естественный сдвиг биологических часов в подростковом возрасте.`},{prompt:`What can make the delay in sleep worse?`,options:[`Movement sensors`,`Early breakfast`,`Bright screens`,`Sleep diaries`],answer:2,quote:`Bright screens can delay sleep further`,explanationRu:`Яркие экраны могут дополнительно отодвигать засыпание.`},{prompt:`How long did one school use the later start?`,options:[`Six days`,`Six weeks`,`One term`,`A full year`],answer:1,quote:`for six weeks`,explanationRu:`Эксперимент с поздним началом длился шесть недель.`},{prompt:`Why did students wear movement sensors?`,options:[`To replace all school tests`,`To record sports scores`,`To avoid depending only on diaries`,`To change their body clocks`],answer:2,quote:`we did not rely only on diaries`,explanationRu:`Датчики дали объективные данные помимо дневников.`},{prompt:`How much extra sleep did the later-start group get on average?`,options:[`Fourteen minutes`,`Twenty minutes`,`Thirty-four minutes`,`One hour`],answer:2,quote:`an average of thirty-four minutes more`,explanationRu:`Средняя прибавка сна составила тридцать четыре минуты.`},{prompt:`Which result did not improve?`,options:[`First-lesson concentration`,`Punctuality`,`Total test scores`,`Length of sleep`],answer:2,quote:`Their total test scores did not rise`,explanationRu:`Общий результат тестов не вырос.`},{prompt:`Why is Professor Hall cautious about a general recommendation?`,options:[`The sensors were broken`,`The sample was small`,`The schools started at seven`,`Students disliked spring`],answer:1,quote:`Our sample was small`,explanationRu:`Профессор не обобщает результат из-за небольшой выборки.`}]}),r({slug:`community-theatre`,title:`Making theatre with a neighbourhood`,topic:`culture`,cefr:`B1`,voices:n[3],dialogue:[`Noah directs a community theatre. How do you choose the stories for your productions?`,`We collect memories from local residents before a writer creates the script. Our latest play began with stories about a market that closed twenty years ago, not with an existing book.`,`Are all the performers experienced actors?`,`About half have never acted before. We hold open workshops instead of competitive auditions, then find roles that fit each person; a shy participant might begin by recording sound effects.`,`What was the hardest part of staging the market play?`,`We could not build thirty realistic stalls in our small hall. A designer used six movable wooden frames, and the audience imagined new locations as the actors rearranged them.`,`How do you know whether the project benefits the community?`,`After each show we invite the audience to add a memory to a wall map. This year we will interview participants six months later too, because ticket numbers alone cannot show whether people feel more connected.`],questions:[{prompt:`What was the source of the theatre’s latest play?`,options:[`A famous novel`,`Residents’ memories of a market`,`A television comedy`,`Actors’ school essays`],answer:1,quote:`stories about a market that closed twenty years ago`,explanationRu:`Пьеса выросла из воспоминаний о закрывшемся рынке.`},{prompt:`When does a writer begin creating the script?`,options:[`Before meeting residents`,`After memories are collected`,`During the final show`,`After tickets sell out`],answer:1,quote:`collect memories from local residents before a writer creates the script`,explanationRu:`Сначала собирают воспоминания, затем автор пишет сценарий.`},{prompt:`How does the theatre select participants?`,options:[`Through competitive auditions`,`Only from drama schools`,`Through open workshops`,`By online voting`],answer:2,quote:`We hold open workshops instead of competitive auditions`,explanationRu:`Вместо конкурсных проб проводятся открытые мастерские.`},{prompt:`What might a shy newcomer do first?`,options:[`Direct the whole play`,`Record sound effects`,`Sell every ticket`,`Write a new novel`],answer:1,quote:`a shy participant might begin by recording sound effects`,explanationRu:`Застенчивому новичку могут поручить запись звуковых эффектов.`},{prompt:`Why could the team not build realistic market stalls?`,options:[`The hall was too small`,`Wood was forbidden`,`The designer left`,`Actors refused to move them`],answer:0,quote:`in our small hall`,explanationRu:`Ограничением был маленький театральный зал.`},{prompt:`How many movable frames represented the market?`,options:[`Four`,`Six`,`Twenty`,`Thirty`],answer:1,quote:`six movable wooden frames`,explanationRu:`Декорация состояла из шести подвижных рам.`},{prompt:`Why will participants be interviewed six months later?`,options:[`To replace the wall map`,`To choose the next actors`,`To measure lasting community connection`,`To sell more market stalls`],answer:2,quote:`ticket numbers alone cannot show whether people feel more connected`,explanationRu:`Позднее интервью поможет оценить устойчивое чувство связи, которого не видно по билетам.`}]}),r({slug:`accessible-app`,title:`Designing an accessible travel app`,topic:`technology`,cefr:`B2`,voices:n[4],dialogue:[`Leila leads a team building a travel app for users with different access needs. Where did the project begin?`,`A friend who uses a wheelchair showed me that a station marked accessible might have a lift on only one platform. We began by recording exact routes through five stations rather than repeating broad official labels.`,`How do you make sure the information remains accurate?`,`Transport staff provide planned changes, but users report broken lifts in real time. We publish a warning after two independent reports and remove it only when a staff member or trusted local reviewer confirms the repair.`,`Does the app focus only on wheelchair access?`,`No. It offers high-contrast maps, step-free routes and quiet-space information. Blind testers asked us to describe landmarks in walking directions instead of saying only turn left after fifty metres.`,`What has been the most difficult design decision?`,`People wanted many filters, but a crowded first screen was itself a barrier. We now ask about priorities during setup and show three main options. Next, we are testing offline directions because underground stations often lose signal.`],questions:[{prompt:`What problem did Leila’s friend identify?`,options:[`A station label hid a one-platform lift limitation`,`Tickets could not be bought online`,`Maps used the wrong city names`,`Trains did not carry bicycles`],answer:0,quote:`a station marked accessible might have a lift on only one platform`,explanationRu:`Общая метка доступности скрывала, что лифт есть лишь на одной платформе.`},{prompt:`What did the team document first?`,options:[`National ticket prices`,`Exact routes through five stations`,`Every underground timetable`,`Hotel wheelchair sizes`],answer:1,quote:`recording exact routes through five stations`,explanationRu:`Сначала команда описала точные маршруты по пяти станциям.`},{prompt:`When does the app publish a broken-lift warning?`,options:[`After one anonymous message`,`After a weekly meeting`,`After two independent reports`,`Only after official repairs`],answer:2,quote:`after two independent reports`,explanationRu:`Предупреждение появляется после двух независимых сообщений.`},{prompt:`Who can confirm that a lift warning should be removed?`,options:[`Any first-time visitor`,`A staff member or trusted reviewer`,`Only the app designer`,`Two hotel managers`],answer:1,quote:`a staff member or trusted local reviewer confirms the repair`,explanationRu:`Снятие предупреждения требует подтверждения сотрудника или доверенного местного проверяющего.`},{prompt:`What did blind testers request in walking directions?`,options:[`More ticket prices`,`Descriptions of landmarks`,`Fewer station names`,`Only distance in metres`],answer:1,quote:`describe landmarks in walking directions`,explanationRu:`Незрячие тестировщики попросили описывать ориентиры.`},{prompt:`Why were many filters not shown on the first screen?`,options:[`Filters cost too much`,`No users wanted them`,`A crowded screen created a barrier`,`The app worked only offline`],answer:2,quote:`a crowded first screen was itself a barrier`,explanationRu:`Перегруженный экран сам ухудшал доступность.`},{prompt:`What feature is the team testing next?`,options:[`Offline directions`,`Restaurant booking`,`A railway game`,`Voice translation`],answer:0,quote:`testing offline directions`,explanationRu:`Следующим тестируется режим маршрутов без интернета.`}]}),r({slug:`zero-waste-restaurant`,title:`Reducing waste in a restaurant`,topic:`food`,cefr:`B2`,voices:n[0],dialogue:[`Chef Oliver runs a restaurant that has sharply reduced food waste. Which change produced the quickest result?`,`We replaced the enormous menu with twelve dishes that share ingredients. That let us buy more accurately, and waste fell before we purchased any special equipment.`,`How do you use ingredients that kitchens often discard?`,`Vegetable stems become stock, stale bread becomes crumbs, and orange peel flavours a syrup. We never serve something merely to avoid waste; every reused ingredient must still improve the dish.`,`What happens to food that remains safe but cannot be served that day?`,`A local charity collects labelled portions at closing time. We freeze them only when the charity requests it, because freezing everything would consume energy and create storage problems.`,`Have customers accepted the changes, and what is still difficult?`,`Most guests appreciate smaller portions with free second helpings. The hardest waste is caused by unpredictable group cancellations, so from next month large bookings will confirm numbers forty-eight hours ahead.`],questions:[{prompt:`Which measure reduced waste most quickly?`,options:[`Buying freezers`,`Introducing twelve connected dishes`,`Closing at lunchtime`,`Serving only soup`],answer:1,quote:`replaced the enormous menu with twelve dishes that share ingredients`,explanationRu:`Быстрый эффект дала короткая карта из двенадцати блюд с общими продуктами.`},{prompt:`Why did the new menu improve purchasing?`,options:[`Ingredients became free`,`Suppliers delivered daily`,`The restaurant could estimate needs better`,`Customers chose meals earlier`],answer:2,quote:`That let us buy more accurately`,explanationRu:`Сокращённое меню позволило точнее закупать нужное количество.`},{prompt:`What is orange peel used to make?`,options:[`A flavoured syrup`,`Bread crumbs`,`Vegetable stock`,`Frozen portions`],answer:0,quote:`orange peel flavours a syrup`,explanationRu:`Апельсиновая кожура используется для ароматного сиропа.`},{prompt:`What condition applies to every reused ingredient?`,options:[`It must be invisible`,`It must be served raw`,`It must improve the food`,`It must come from a charity`],answer:2,quote:`must still improve the dish`,explanationRu:`Повторное использование допустимо только если продукт улучшает блюдо.`},{prompt:`When is safe leftover food collected?`,options:[`Before breakfast`,`At closing time`,`Once a week`,`Forty-eight hours later`],answer:1,quote:`collects labelled portions at closing time`,explanationRu:`Благотворительная организация забирает подписанные порции при закрытии.`},{prompt:`How does the restaurant handle portion size?`,options:[`Large portions with no extras`,`Only one fixed tasting plate`,`Smaller portions and free seconds`,`Customers bring containers first`],answer:2,quote:`smaller portions with free second helpings`,explanationRu:`Порции уменьшены, но бесплатная добавка доступна.`},{prompt:`What will large groups have to do?`,options:[`Pay only in cash`,`Order twelve dishes`,`Bring their own food`,`Confirm attendance two days before`],answer:3,quote:`confirm numbers forty-eight hours ahead`,explanationRu:`Большие группы должны подтвердить число гостей за сорок восемь часов.`}]}),r({slug:`language-exchange`,title:`A neighbourhood language exchange`,topic:`education`,cefr:`B1`,voices:n[1],dialogue:[`Amira coordinates a weekly language exchange. How is it different from a normal language class?`,`There is no teacher and no fixed textbook. Partners spend twenty-five minutes in one language and twenty-five in the other, then write down one useful expression they learned from conversation.`,`How do you match people who have never met?`,`We consider language level and shared interests, not age or profession. Beginners meet patient speakers who can explain with examples, while advanced learners often choose partners interested in the same news topics.`,`What problem did you notice during the first few months?`,`Confident speakers sometimes used almost all the time in their preferred language. We introduced a visible timer and coloured cards that either partner can raise when it is time to switch.`,`Has the exchange created anything beyond language practice?`,`Yes. Two members now run a bilingual cooking club, and several newcomers found local friends. Next term we will add one online evening, but the Saturday meeting will remain face to face.`],questions:[{prompt:`How much time do partners spend in each language?`,options:[`Fifteen minutes`,`Twenty-five minutes`,`Forty minutes`,`One hour`],answer:1,quote:`twenty-five minutes in one language and twenty-five in the other`,explanationRu:`На каждый язык выделяется по двадцать пять минут.`},{prompt:`What do partners record after talking?`,options:[`One useful expression`,`Their partner’s profession`,`A complete textbook chapter`,`Every grammar error`],answer:0,quote:`write down one useful expression`,explanationRu:`После разговора записывают одно полезное выражение.`},{prompt:`Which factor is used when matching partners?`,options:[`Their age`,`Their salary`,`A shared interest`,`Their street address`],answer:2,quote:`We consider language level and shared interests`,explanationRu:`При подборе учитываются уровень языка и общие интересы.`},{prompt:`What quality is sought in partners for beginners?`,options:[`Patience`,`Professional teaching certificates`,`The same age`,`Advanced cooking skills`],answer:0,quote:`Beginners meet patient speakers`,explanationRu:`Новичкам подбирают терпеливых собеседников.`},{prompt:`What difficulty appeared at first?`,options:[`Nobody brought a textbook`,`One language could dominate the meeting`,`The room was too bright`,`Beginners refused examples`],answer:1,quote:`used almost all the time in their preferred language`,explanationRu:`Уверенные участники иногда занимали почти всё время предпочитаемым языком.`},{prompt:`What helps partners change languages on time?`,options:[`A teacher’s bell`,`An online test`,`A timer and coloured cards`,`A cooking recipe`],answer:2,quote:`a visible timer and coloured cards`,explanationRu:`Для смены языка ввели видимый таймер и цветные карточки.`},{prompt:`Which meeting will continue in person?`,options:[`The Saturday meeting`,`The new online evening`,`The cooking club only`,`Every weekday morning`],answer:0,quote:`the Saturday meeting will remain face to face`,explanationRu:`Субботняя встреча останется очной.`}]}),r({slug:`flood-ready-gardens`,title:`Gardens that cope with heavy rain`,topic:`nature`,cefr:`B2`,voices:n[2],dialogue:[`Landscape architect Ben designs gardens that reduce local flooding. Why can an ordinary garden make a difference?`,`Many front gardens have been covered with concrete, so rain reaches drains almost instantly. Soil and plants hold water temporarily, reducing the sudden pressure on pipes during a storm.`,`What did you change in your recent school project?`,`We lowered one planted area by fifteen centimetres so roof water flows into it. Native grasses tolerate both wet and dry periods, and a gravel path lets water pass through instead of running to the road.`,`Were parents worried that the new garden would become a permanent pond?`,`They were, so we demonstrated that the basin empties within twenty-four hours after normal rain. It holds water longer only during an extreme storm, when keeping it away from classrooms matters most.`,`How will you judge whether the design works?`,`Pupils measure rainfall and water depth, while the council checks the nearby drain. We need data from at least two winters before changing other schools, although insect surveys have already shown more species.`],questions:[{prompt:`Why does concrete increase pressure on drains?`,options:[`It sends rainwater to them very quickly`,`It absorbs too much water`,`It damages all garden plants`,`It makes storms last longer`],answer:0,quote:`rain reaches drains almost instantly`,explanationRu:`С бетона вода почти сразу попадает в ливневую систему.`},{prompt:`How much was the planted area lowered?`,options:[`Five centimetres`,`Ten centimetres`,`Fifteen centimetres`,`Fifty centimetres`],answer:2,quote:`lowered one planted area by fifteen centimetres`,explanationRu:`Посаженный участок понизили на пятнадцать сантиметров.`},{prompt:`Why were native grasses selected?`,options:[`They need no sunlight`,`They manage both wet and dry conditions`,`They grow only in gravel`,`They prevent every insect`],answer:1,quote:`Native grasses tolerate both wet and dry periods`,explanationRu:`Местные травы выдерживают и влажные, и сухие периоды.`},{prompt:`What is the advantage of the gravel path?`,options:[`It changes colour in rain`,`It directs pupils indoors`,`It stores tools`,`It allows water through`],answer:3,quote:`a gravel path lets water pass through`,explanationRu:`Гравийная дорожка пропускает воду в почву.`},{prompt:`How quickly does the basin empty after ordinary rain?`,options:[`Within twenty-four hours`,`Within one week`,`In two winters`,`Only during summer`],answer:0,quote:`empties within twenty-four hours after normal rain`,explanationRu:`После обычного дождя чаша освобождается за сутки.`},{prompt:`Who monitors the nearby drain?`,options:[`The parents`,`The council`,`The architect alone`,`The insect survey team`],answer:1,quote:`the council checks the nearby drain`,explanationRu:`Состояние соседнего стока проверяет муниципалитет.`},{prompt:`Why will the team wait before copying the design elsewhere?`,options:[`No grasses are available`,`The school will close`,`It needs evidence from two winters`,`Parents rejected all gardens`],answer:2,quote:`data from at least two winters before changing other schools`,explanationRu:`Перед масштабированием нужны данные минимум за две зимы.`}]}),r({slug:`museum-conservator`,title:`Protecting a painted theatre curtain`,topic:`art`,cefr:`B2`,voices:n[3],dialogue:[`Conservator Hannah Reed is restoring a century-old painted theatre curtain. What condition was it in?`,`It had been folded in a damp store for thirty years. The paint was lifting in hundreds of places, but the main image was complete because the outer fabric had protected it from light.`,`What was the first thing your team did?`,`Before cleaning anything, we photographed every square and tested tiny areas with different materials. Water removed dirt well but also softened the red paint, so we chose a dry cleaning method.`,`Can you repaint sections that have lost colour?`,`Our aim is not to make the curtain look new. We secure original paint and add colour only where a white loss distracts from the image; the added material must be removable by a future conservator.`,`Will visitors be able to see the curtain after restoration?`,`Yes, but it will hang only for three months each year behind filtered glass. A digital projection will show it during the other months, and the original will rest rolled around a wide tube rather than folded.`],questions:[{prompt:`How long had the curtain been kept in a damp store?`,options:[`Three years`,`Thirteen years`,`Thirty years`,`A century`],answer:2,quote:`in a damp store for thirty years`,explanationRu:`Занавес хранился во влажном помещении тридцать лет.`},{prompt:`Why was the main painted image still complete?`,options:[`It had been repainted`,`Outer fabric shielded it from light`,`The store was dry`,`Visitors cleaned it`],answer:1,quote:`the outer fabric had protected it from light`,explanationRu:`Внешний слой ткани защитил изображение от света.`},{prompt:`What did the team do before cleaning?`,options:[`Photographed the whole surface in sections`,`Hung it in the theatre`,`Added red paint`,`Rolled it onto a tube`],answer:0,quote:`we photographed every square`,explanationRu:`Перед очисткой специалисты сфотографировали каждый участок.`},{prompt:`Why was water not chosen for cleaning?`,options:[`It made the cloth too heavy`,`It cost too much`,`It affected the red paint`,`It failed to remove dirt`],answer:2,quote:`also softened the red paint`,explanationRu:`Вода размягчала красочный слой красного цвета.`},{prompt:`What is the main restoration goal?`,options:[`To make the curtain look new`,`To preserve original paint`,`To replace the main image`,`To hide all signs of age`],answer:1,quote:`We secure original paint`,explanationRu:`Главная задача — закрепить оригинальную краску, а не обновить предмет.`},{prompt:`How long will the original curtain be displayed annually?`,options:[`Three months`,`Six months`,`Nine months`,`All year`],answer:0,quote:`only for three months each year`,explanationRu:`Оригинал будут показывать только три месяца в году.`},{prompt:`How will the curtain be stored between displays?`,options:[`Folded in a box`,`Behind open glass`,`Flat on the floor`,`Rolled around a wide tube`],answer:3,quote:`rolled around a wide tube rather than folded`,explanationRu:`Для хранения его намотают на широкую трубу вместо складывания.`}]}),r({slug:`mountain-rescue`,title:`Volunteering with mountain rescue`,topic:`safety`,cefr:`B2`,voices:n[4],dialogue:[`Tariq volunteers with a mountain rescue team. What training did you need before joining real operations?`,`I already climbed regularly, but that was not enough. I completed a six-month programme in navigation, first aid and radio procedure, then passed a night exercise in poor weather.`,`What information helps the team most when someone calls for help?`,`An exact phone location is useful, yet battery percentage and clothing matter too. If contact may be lost, we need to know whether the person can stay warm while we travel towards them.`,`Are most incidents caused by people taking obvious risks?`,`No. Weather changes quickly, and a small ankle injury can become serious far from a road. Last year our most common task was assisting careful walkers who could no longer continue, not rescuing reckless climbers.`,`How has technology changed your work?`,`Digital maps help teams share positions, but we still carry paper maps because phones fail in cold conditions. We recently added a small drone for searching open ground; it cannot fly safely in strong wind or replace people in difficult terrain.`],questions:[{prompt:`How long was Tariq’s rescue training programme?`,options:[`Six weeks`,`Six months`,`One year`,`Two weekends`],answer:1,quote:`a six-month programme`,explanationRu:`Подготовка длилась шесть месяцев.`},{prompt:`What final assessment did Tariq pass?`,options:[`A daytime climbing race`,`A written medical exam only`,`A night exercise in bad weather`,`A drone flight`],answer:2,quote:`passed a night exercise in poor weather`,explanationRu:`Итоговым испытанием было ночное учение в плохую погоду.`},{prompt:`Why does the team ask about a caller’s clothing?`,options:[`To identify their profession`,`To judge whether they can remain warm`,`To choose a helicopter colour`,`To estimate their climbing speed`],answer:1,quote:`whether the person can stay warm`,explanationRu:`Одежда помогает оценить способность пострадавшего сохранять тепло.`},{prompt:`Who did the team assist most often last year?`,options:[`Careful walkers unable to continue`,`Reckless climbers on closed routes`,`Drone pilots`,`Drivers near the station`],answer:0,quote:`assisting careful walkers who could no longer continue`,explanationRu:`Чаще всего помогали осторожным туристам, которые не могли идти дальше.`},{prompt:`Why are paper maps still carried?`,options:[`Digital maps are illegal`,`Phones can fail in cold weather`,`Paper maps show clothing`,`Drones require them`],answer:1,quote:`phones fail in cold conditions`,explanationRu:`Бумажные карты нужны на случай отказа телефона на холоде.`},{prompt:`Where is the new drone intended to search?`,options:[`Inside caves`,`Underwater`,`Open ground`,`Crowded streets`],answer:2,quote:`a small drone for searching open ground`,explanationRu:`Дрон предназначен для поиска на открытой местности.`},{prompt:`What prevents the drone from flying safely?`,options:[`Strong wind`,`Darkness`,`Paper maps`,`A low mountain`],answer:0,quote:`cannot fly safely in strong wind`,explanationRu:`Безопасному полёту мешает сильный ветер.`}]}),r({slug:`ethical-fashion`,title:`Tracing a jacket from fibre to shop`,topic:`business`,cefr:`B1`,voices:n[0],dialogue:[`Designer Ruby Patel recently launched a jacket with a traceable supply chain. What does traceable mean here?`,`A code inside the jacket shows where the cotton grew, where the fabric was woven and which workshop made the garment. It does not reveal workers’ names, because transparency must not remove their privacy.`,`Was finding suppliers willing to share this information easy?`,`The cotton farm already kept detailed records, but two factories refused our request. We chose a smaller workshop that published wage ranges and allowed an independent safety inspection.`,`Does more responsible production always make clothing much more expensive?`,`Our jacket costs about twelve percent more than the previous model. We reduced the difference by using one colour and keeping the same design for two seasons instead of following every short trend.`,`How should customers care for the jacket, and what happens if it is damaged?`,`Washing it less often and using cool water saves energy and protects the fabric. We provide spare buttons free, and customers can return a torn jacket for a fixed-price repair rather than replacing it.`],questions:[{prompt:`What can a buyer learn from the code inside the jacket?`,options:[`The buyer’s personal size history`,`The production locations`,`Every worker’s name`,`Future fashion trends`],answer:1,quote:`shows where the cotton grew, where the fabric was woven and which workshop made the garment`,explanationRu:`Код показывает места выращивания, ткачества и пошива.`},{prompt:`Why are individual workers not named?`,options:[`Their privacy is protected`,`The workshop has no records`,`The code is too short`,`Customers requested secrecy`],answer:0,quote:`transparency must not remove their privacy`,explanationRu:`Имена не публикуются для защиты личной жизни работников.`},{prompt:`Why was the smaller workshop selected?`,options:[`It offered many colours`,`It followed every trend`,`It published pay ranges and accepted inspection`,`It refused all records`],answer:2,quote:`published wage ranges and allowed an independent safety inspection`,explanationRu:`Мастерская раскрыла диапазоны оплаты и допустила независимую проверку безопасности.`},{prompt:`How much more does the new jacket cost?`,options:[`About two percent`,`About twelve percent`,`About twenty percent`,`Twice as much`],answer:1,quote:`costs about twelve percent more`,explanationRu:`Цена выше примерно на двенадцать процентов.`},{prompt:`Which design decision helped control the price?`,options:[`Using one colour`,`Changing it monthly`,`Adding more buttons`,`Making it disposable`],answer:0,quote:`using one colour`,explanationRu:`Снизить разницу в цене помог выбор одного цвета.`},{prompt:`What washing advice does Ruby give?`,options:[`Wash it daily in hot water`,`Dry-clean after every use`,`Wash less and use cool water`,`Never clean the jacket`],answer:2,quote:`Washing it less often and using cool water`,explanationRu:`Совет — стирать реже и в прохладной воде.`},{prompt:`What can customers receive without charge?`,options:[`A new jacket`,`Spare buttons`,`A factory visit`,`A second colour`],answer:1,quote:`provide spare buttons free`,explanationRu:`Запасные пуговицы предоставляются бесплатно.`}]}),r({slug:`wildlife-photographer`,title:`Photographing animals without disturbance`,topic:`nature`,cefr:`B1`,voices:n[1],dialogue:[`Photographer Grace Kim specialises in urban wildlife. Why work in towns rather than remote forests?`,`Animals in cities live beside millions of people but are often unnoticed. I can return to the same park throughout the year, which teaches me more than a single expensive trip abroad.`,`How do you avoid disturbing the animals you photograph?`,`I use a long lens and stay on public paths. If a bird stops feeding or repeatedly looks at me, I move away; getting a dramatic picture is never more important than normal behaviour.`,`Which photograph required the greatest patience?`,`A family of foxes crossed an old railway bridge just before sunrise. I visited fourteen mornings before they appeared in good light, and on most days I took no photographs at all.`,`Do you edit your images before publishing them?`,`I adjust brightness and crop the frame, but I never add or remove an animal. Captions include the date and general area, although I hide precise nest locations to protect them from crowds.`],questions:[{prompt:`What advantage does photographing a local park give Grace?`,options:[`She can revisit it across seasons`,`Every animal is easier to see`,`No people enter it`,`Equipment is unnecessary`],answer:0,quote:`return to the same park throughout the year`,explanationRu:`Местный парк можно регулярно посещать в течение всего года.`},{prompt:`Where does Grace remain while photographing animals?`,options:[`Inside nests`,`On public paths`,`Behind private fences`,`In moving cars`],answer:1,quote:`stay on public paths`,explanationRu:`Она остаётся на общественных дорожках.`},{prompt:`What animal behaviour tells Grace to move away?`,options:[`A bird continues feeding`,`A fox crosses a bridge`,`A bird stops eating and watches her`,`An animal appears in good light`],answer:2,quote:`If a bird stops feeding or repeatedly looks at me, I move away`,explanationRu:`Остановка кормления и постоянное наблюдение за фотографом означают беспокойство.`},{prompt:`Where did Grace photograph the fox family?`,options:[`Near a nest`,`On an old railway bridge`,`In a remote forest`,`Beside a school`],answer:1,quote:`crossed an old railway bridge`,explanationRu:`Лисы пересекали старый железнодорожный мост.`},{prompt:`How many mornings did Grace wait for the fox photograph?`,options:[`Four`,`Ten`,`Fourteen`,`Forty`],answer:2,quote:`I visited fourteen mornings`,explanationRu:`Она приходила четырнадцать утр.`},{prompt:`Which editing action does Grace refuse to do?`,options:[`Adjust brightness`,`Crop the frame`,`Write a caption`,`Add or remove an animal`],answer:3,quote:`I never add or remove an animal`,explanationRu:`Она принципиально не добавляет и не удаляет животных на снимке.`},{prompt:`Why are exact nest locations omitted?`,options:[`To protect nests from crowds`,`Because Grace forgets them`,`To shorten every caption`,`Because parks ban dates`],answer:0,quote:`hide precise nest locations to protect them from crowds`,explanationRu:`Точные координаты скрывают, чтобы не привлекать толпу к гнёздам.`}]}),r({slug:`digital-library`,title:`A library beyond printed books`,topic:`society`,cefr:`B1`,voices:n[2],dialogue:[`Librarian Victor runs digital services at a public library. Which service is most popular?`,`Electronic book loans are growing, but our weekly device-help desk attracts the widest age range. People bring their own phones or tablets and learn one task instead of handing the device over for repair.`,`What kinds of task do visitors ask about?`,`Younger adults often need help completing online forms, while older visitors ask about video calls and photo storage. Staff never enter banking passwords, and private financial transactions are outside the service.`,`How do people use the library’s new recording room?`,`Students record presentations, local groups make podcasts, and families digitise spoken memories. The room is free for members, but they must book because only two people can use it at once.`,`Will digital services eventually replace shelves of books?`,`No. Printed borrowing remains strong, and some users come specifically to escape screens. We are moving reference books upstairs to create a larger teaching area, not removing the collection.`],questions:[{prompt:`Which library service attracts the broadest range of ages?`,options:[`Electronic loans`,`The device-help desk`,`The recording room`,`Printed reference books`],answer:1,quote:`our weekly device-help desk attracts the widest age range`,explanationRu:`Самая широкая возрастная аудитория у еженедельной помощи с устройствами.`},{prompt:`What is the aim of a device-help visit?`,options:[`To replace a broken phone`,`To sell a tablet`,`To teach one specific task`,`To collect banking passwords`],answer:2,quote:`learn one task instead of handing the device over for repair`,explanationRu:`Сотрудник обучает одной задаче, а не забирает устройство в ремонт.`},{prompt:`What do younger adults often need assistance with?`,options:[`Online forms`,`Video calls only`,`Book binding`,`Camera repair`],answer:0,quote:`Younger adults often need help completing online forms`,explanationRu:`Молодые взрослые часто обращаются за помощью с онлайн-формами.`},{prompt:`Which activity is excluded from the help service?`,options:[`Photo storage`,`Video calls`,`Private financial transactions`,`Public online forms`],answer:2,quote:`private financial transactions are outside the service`,explanationRu:`Личные финансовые операции в услугу не входят.`},{prompt:`How much does the recording room cost library members?`,options:[`Nothing`,`A daily fee`,`The price of an e-book`,`A yearly studio charge`],answer:0,quote:`The room is free for members`,explanationRu:`Для членов библиотеки студия бесплатна.`},{prompt:`Why must the recording room be reserved?`,options:[`It has no internet`,`It holds only two people`,`Books are stored there`,`Staff use it all day`],answer:1,quote:`only two people can use it at once`,explanationRu:`Комната вмещает только двух человек, поэтому нужна запись.`},{prompt:`Why are reference books being moved upstairs?`,options:[`To sell them`,`To hide them from users`,`To expand a teaching space`,`To end printed borrowing`],answer:2,quote:`to create a larger teaching area, not removing the collection`,explanationRu:`Перемещение освобождает большую учебную зону, а книги не убирают из фонда.`}]}),r({slug:`robotics-mentor`,title:`Mentoring a school robotics team`,topic:`education`,cefr:`B2`,voices:n[3],dialogue:[`Engineer Chloe mentors a school robotics team. What challenge are the students preparing for?`,`Their robot must sort coloured blocks, cross a rough surface and place one block on a shelf. Teams receive points for each task, so a reliable partial solution can beat an ambitious machine that often fails.`,`How do you divide work among students with different experience?`,`Everyone rotates through building, programming and testing during the first month. Afterwards they choose a focus, but each design decision needs one student from another group to review it.`,`What was the team’s biggest recent mistake?`,`They improved the lifting arm for two weeks without timing the whole course. The arm worked beautifully, but the robot finished nine seconds late. Now every Friday ends with a complete timed run.`,`What is your role during the actual competition?`,`Mentors may ask questions but cannot touch the robot or give direct instructions. I help students prepare a decision checklist beforehand, then they solve unexpected problems independently on the day.`],questions:[{prompt:`Which object must the robot place on a shelf?`,options:[`A coloured block`,`A timing clock`,`A rough wheel`,`A checklist`],answer:0,quote:`place one block on a shelf`,explanationRu:`Одна из задач — поставить цветной блок на полку.`},{prompt:`Why might a simpler robot win?`,options:[`Judges dislike ambitious designs`,`Reliable partial success earns points`,`The shelf is optional`,`Mentors control it`],answer:1,quote:`a reliable partial solution can beat an ambitious machine that often fails`,explanationRu:`Стабильное выполнение части задач может дать больше баллов, чем ненадёжная сложная конструкция.`},{prompt:`What do all students do in the first month?`,options:[`Only programming`,`Choose one permanent role`,`Rotate through three types of work`,`Compete without testing`],answer:2,quote:`Everyone rotates through building, programming and testing during the first month`,explanationRu:`Первый месяц все по очереди занимаются сборкой, программированием и тестами.`},{prompt:`Who must review each design decision?`,options:[`A student from another group`,`A competition judge`,`Only Chloe`,`A parent`],answer:0,quote:`one student from another group to review it`,explanationRu:`Решение проверяет ученик из другой рабочей группы.`},{prompt:`What caused the team to finish late?`,options:[`A block was the wrong colour`,`It ignored total course timing`,`The robot crossed no rough surface`,`The mentor touched the robot`],answer:1,quote:`without timing the whole course`,explanationRu:`Команда улучшала деталь, но не измеряла время всего маршрута.`},{prompt:`What now happens every Friday?`,options:[`Students change schools`,`The arm is removed`,`A full timed run`,`Mentors build the robot`],answer:2,quote:`every Friday ends with a complete timed run`,explanationRu:`По пятницам проводится полный заезд с измерением времени.`},{prompt:`What is Chloe forbidden to do at the competition?`,options:[`Ask questions`,`Prepare a checklist earlier`,`Watch the students`,`Touch the robot or give direct orders`],answer:3,quote:`cannot touch the robot or give direct instructions`,explanationRu:`Во время соревнования наставник не может касаться робота или давать прямые указания.`}]}),r({slug:`youth-council`,title:`Young people advising a town council`,topic:`society`,cefr:`B2`,voices:n[4],dialogue:[`Jonas chairs a youth council that advises the town government. How are members chosen?`,`Schools and youth clubs each nominate candidates, then young residents aged thirteen to nineteen vote online. Seats are reserved for different neighbourhoods so the town centre cannot dominate every decision.`,`Can the youth council actually influence spending?`,`It controls a small annual fund of fifteen thousand pounds and recommends changes to larger projects. Last year members funded water fountains themselves and persuaded the transport committee to test a later evening bus.`,`What happens when members disagree strongly?`,`They first publish two short position notes with evidence, then hold a meeting led by someone outside the debate. A vote comes only after every side has answered questions from the others.`,`What are you working on now?`,`We are mapping places where teenagers feel unsafe after dark. The map will not display individual reports publicly; it will show combined patterns to the council, which protects privacy while revealing where lighting needs inspection.`],questions:[{prompt:`Who votes for youth council candidates?`,options:[`Only school teachers`,`Town employees`,`Residents aged thirteen to nineteen`,`All national voters`],answer:2,quote:`young residents aged thirteen to nineteen vote online`,explanationRu:`Голосуют молодые жители в возрасте от тринадцати до девятнадцати лет.`},{prompt:`Why are seats linked to neighbourhoods?`,options:[`To prevent the centre controlling all decisions`,`To shorten online voting`,`To remove youth clubs`,`To increase the age limit`],answer:0,quote:`so the town centre cannot dominate every decision`,explanationRu:`Распределение мест не позволяет центру города доминировать во всех решениях.`},{prompt:`How large is the council’s own annual fund?`,options:[`Five thousand pounds`,`Fifteen thousand pounds`,`Fifty thousand pounds`,`One hundred thousand pounds`],answer:1,quote:`a small annual fund of fifteen thousand pounds`,explanationRu:`Собственный годовой фонд составляет пятнадцать тысяч фунтов.`},{prompt:`Which project did members pay for directly?`,options:[`An evening bus`,`New school buildings`,`Water fountains`,`Online voting software`],answer:2,quote:`members funded water fountains themselves`,explanationRu:`Из своего фонда молодёжный совет оплатил питьевые фонтанчики.`},{prompt:`What is published before a meeting on a disputed issue?`,options:[`Two evidence-based position notes`,`Individual private reports`,`A final decision`,`Every member’s address`],answer:0,quote:`publish two short position notes with evidence`,explanationRu:`Перед обсуждением публикуются две краткие позиции с доказательствами.`},{prompt:`When does the youth council vote on a disagreement?`,options:[`Before reading any evidence`,`After each side answers questions`,`Only after a national election`,`As soon as one note appears`],answer:1,quote:`A vote comes only after every side has answered questions`,explanationRu:`Голосование проходит после того, как все стороны ответили на вопросы.`},{prompt:`How will the safety map protect individuals?`,options:[`By deleting every report`,`By naming only schools`,`By hiding all lighting problems`,`By showing combined patterns instead of personal reports`],answer:3,quote:`it will show combined patterns to the council`,explanationRu:`Карта покажет объединённые закономерности, а не отдельные сообщения.`}]})],a=[`speaker_a`,`speaker_b`,`speaker_c`,`speaker_d`,`speaker_e`,`speaker_f`],o=[`female_1`,`male_1`,`female_2`,`male_2`,`female_3`,`male_3`];function s({slug:e,title:t,topic:n,cefr:r,statements:i,speakers:s}){return{id:`listening-pilot-v1.matching.${e}`,revision:1,type:`matching`,title:t,topic:n,cefr:r,provenance:`original`,audio:{path:`/audio/listening/listening-pilot-v1/matching/${e}-r1.mp3`},script:s.map((e,t)=>({role:a[t],voiceSlot:o[t],text:e.text})),task:{statements:i,answers:s.map(e=>e.answer),evidence:s.map(e=>({statementIndex:e.answer,quote:e.quote,explanationRu:e.explanationRu}))}}}function c({slug:e,title:t,topic:n,cefr:r,voices:i,dialogue:a,items:o}){return{id:`listening-pilot-v1.true-false.${e}`,revision:1,type:`true_false`,title:t,topic:n,cefr:r,provenance:`original`,audio:{path:`/audio/listening/listening-pilot-v1/true-false/${e}-r1.mp3`},script:a.map((e,t)=>({role:t%2==0?`speaker_a`:`speaker_b`,voiceSlot:i[t%2],text:e})),task:{statements:o.map(e=>e.statement),answers:o.map(e=>e.answer),evidence:o.map(e=>({answer:e.answer,quote:e.quote,explanationRu:e.explanationRu}))}}}var l=[s({slug:`study-methods`,title:`How I prepare for tests`,topic:`education`,cefr:`B1`,statements:[`The speaker follows a detailed revision timetable.`,`The speaker understands material by explaining it to somebody else.`,`The speaker can only concentrate in a quiet place.`,`The speaker studies with recordings made in their own voice.`,`The speaker often delays work until the last moment.`,`The speaker uses small rewards to remain motivated.`,`The speaker prefers to study without any plan.`],speakers:[{answer:3,quote:`I record short summaries on my phone`,explanationRu:`Ученик записывает собственные краткие объяснения и слушает их по дороге.`,text:`Reading the same page again does not help me much. I record short summaries on my phone and listen to them while I am walking to school, so difficult facts stay in my memory.`},{answer:1,quote:`I teach the topic to my younger brother`,explanationRu:`Главный способ — объяснить тему другому человеку и заметить пробелы.`,text:`Before a test, I teach the topic to my younger brother, even if he is not interested in it. When I cannot explain an idea simply, I know exactly what I need to revise.`},{answer:4,quote:`I keep finding other things to do`,explanationRu:`Говорящий откладывает подготовку и начинает слишком поздно.`,text:`I always promise to start preparing two weeks early, but I keep finding other things to do. In the end, I usually open my books the evening before the test and regret it.`},{answer:2,quote:`Even quiet music breaks my concentration`,explanationRu:`Для работы ему необходима полная тишина, даже музыка мешает.`,text:`My family knows not to enter my room when I revise. Even quiet music breaks my concentration, so I turn off every device and work best when the house is completely silent.`},{answer:5,quote:`I let myself watch one short episode`,explanationRu:`После выполненного блока занятий она награждает себя коротким отдыхом.`,text:`Long study sessions feel impossible to me, so I divide them into thirty-minute blocks. After each block, I let myself watch one short episode or have a favourite snack.`},{answer:0,quote:`Every subject has its own colour and time slot`,explanationRu:`Подготовка строится по подробному цветному расписанию.`,text:`On Sunday evening I plan the whole school week in a notebook. Every subject has its own colour and time slot, and ticking completed tasks makes me feel calm and organised.`}]}),s({slug:`travel-styles`,title:`The way I like to travel`,topic:`travel`,cefr:`B1`,statements:[`The speaker chooses places that are away from crowds.`,`The speaker thinks local food is the best part of a trip.`,`The speaker enjoys planning every detail before departure.`,`The speaker prefers travelling by train to flying.`,`The speaker likes learning about the past while travelling.`,`The speaker travels mainly to practise a foreign language.`,`The speaker always buys expensive souvenirs.`],speakers:[{answer:2,quote:`I book the rooms and mark every museum on a map`,explanationRu:`Заранее бронируются комнаты и составляется точная карта поездки.`,text:`For me, preparation is almost as enjoyable as the holiday itself. Months before we leave, I book the rooms and mark every museum on a map, including opening times and bus routes.`},{answer:0,quote:`I look for a village that guidebooks hardly mention`,explanationRu:`Он специально ищет малоизвестные места без большого количества туристов.`,text:`Famous resorts make me tired because the streets are full and noisy. I look for a village that guidebooks hardly mention, where I can walk for hours without meeting a tour group.`},{answer:5,quote:`I need to speak Spanish in real situations`,explanationRu:`Основная цель путешествий — практиковать язык с местными жителями.`,text:`Online lessons are useful, but I need to speak Spanish in real situations. I stay with local families and try to solve everyday problems without changing to English.`},{answer:3,quote:`A train journey is part of the adventure`,explanationRu:`Поезд ценится как часть путешествия, в отличие от быстрого перелёта.`,text:`Airports are stressful, and a flight shows you nothing between two cities. A train journey is part of the adventure because I can watch the landscape change and move around freely.`},{answer:1,quote:`my strongest memories are usually connected with meals`,explanationRu:`Самые яркие впечатления связаны с местными блюдами и рынками.`,text:`I may forget the name of a square, but my strongest memories are usually connected with meals. I visit food markets, ask sellers for advice and taste dishes I cannot find at home.`},{answer:4,quote:`Old buildings make historical events feel real`,explanationRu:`История становится понятнее благодаря посещению старых зданий и музеев.`,text:`Old buildings make historical events feel real in a way textbooks never do. I love guided walks through castles and listening to stories about the people who once lived there.`}]}),s({slug:`greener-life`,title:`Small choices for a greener life`,topic:`environment`,cefr:`B2`,statements:[`The speaker has reduced the amount of meat they eat.`,`The speaker repairs things instead of replacing them.`,`The speaker campaigns for better recycling facilities.`,`The speaker avoids unnecessary packaging while shopping.`,`The speaker saves energy by changing household habits.`,`The speaker grows some food at home.`,`The speaker believes individual action is completely useless.`],speakers:[{answer:4,quote:`We stopped leaving devices on standby`,explanationRu:`Семья изменила бытовые привычки, чтобы расходовать меньше электричества.`,text:`Our electricity bill showed how much power we were wasting. We stopped leaving devices on standby, wash clothes at lower temperatures and only heat rooms that we actually use.`},{answer:1,quote:`I first try to find out why it has stopped working`,explanationRu:`Перед покупкой новой вещи он пытается определить поломку и починить старую.`,text:`When an appliance breaks, I first try to find out why it has stopped working. Repair videos and a local workshop have helped me keep several useful things out of the rubbish bin.`},{answer:3,quote:`I take cloth bags and reusable containers`,explanationRu:`Покупатель использует свою тару и избегает одноразовой упаковки.`,text:`Supermarkets wrap far too many products in plastic. I take cloth bags and reusable containers to the market, and I choose loose fruit rather than ready-packed portions.`},{answer:5,quote:`Herbs and tomatoes now grow on my balcony`,explanationRu:`Часть продуктов выращивается дома на небольшом балконе.`,text:`I used to think growing food required a large garden. Herbs and tomatoes now grow on my balcony, and caring for them has made me value seasonal produce much more.`},{answer:0,quote:`I now cook vegetarian meals on most weekdays`,explanationRu:`Количество мясных блюд сократилось, хотя полного отказа от мяса нет.`,text:`I learned that food choices affect the climate as well as our health. I now cook vegetarian meals on most weekdays, although I still eat meat at family celebrations.`},{answer:2,quote:`We collected signatures for separate glass bins`,explanationRu:`Говорящая организовала коллективное обращение за удобной переработкой стекла.`,text:`People in our district wanted to recycle, but the nearest collection point was kilometres away. We collected signatures for separate glass bins, and the council finally installed them.`}]}),s({slug:`digital-habits`,title:`Living with technology`,topic:`technology`,cefr:`B2`,statements:[`The speaker limits notifications to protect their attention.`,`The speaker uses technology to stay close to older relatives.`,`The speaker creates digital art as a hobby.`,`The speaker worries about sharing personal information online.`,`The speaker learns practical skills from online videos.`,`The speaker prefers printed books to electronic ones.`,`The speaker replaces their phone whenever a new model appears.`],speakers:[{answer:0,quote:`only calls from my family can interrupt me`,explanationRu:`Большинство уведомлений отключено, чтобы они не отвлекали от работы.`,text:`Constant messages made it difficult to finish even a short homework task. Now only calls from my family can interrupt me, while social media notifications remain switched off until evening.`},{answer:4,quote:`A video showed me each step clearly`,explanationRu:`Он освоил ремонт велосипеда с помощью пошагового онлайн-видео.`,text:`Last month my bicycle brakes failed, and I had never repaired them before. A video showed me each step clearly, so I fixed the problem without taking the bike to a shop.`},{answer:3,quote:`I check privacy settings before installing anything`,explanationRu:`Говорящая внимательно относится к разрешениям и защите личных данных.`,text:`Some apps ask for access to contacts or location when they do not need it. I check privacy settings before installing anything and avoid posting details about where I live.`},{answer:1,quote:`We have a video call every Sunday`,explanationRu:`Технология помогает регулярно общаться с бабушкой, живущей далеко.`,text:`My grandmother lives in another region and cannot travel easily. We have a video call every Sunday, and I send her photographs during the week so she still feels part of our life.`},{answer:5,quote:`I remember a story better when I turn real pages`,explanationRu:`Бумажные книги нравятся больше электронных из-за ощущений и концентрации.`,text:`Electronic books are convenient on holiday, but I remember a story better when I turn real pages. A printed book also keeps me away from links and messages that break my concentration.`},{answer:2,quote:`Drawing on a tablet gives me endless colours`,explanationRu:`Планшет используется для создания иллюстраций как творческого увлечения.`,text:`Drawing on a tablet gives me endless colours without filling my desk with paint. I make illustrations for friends, experiment with layers and sometimes print the best ones as postcards.`}]}),s({slug:`healthy-routines`,title:`Habits that keep me well`,topic:`health`,cefr:`B1`,statements:[`The speaker improved their sleep by changing an evening habit.`,`The speaker exercises with other people for motivation.`,`The speaker prepares food in advance to eat better.`,`The speaker uses breathing exercises when feeling anxious.`,`The speaker walks instead of using transport for short journeys.`,`The speaker tracks water intake during the day.`,`The speaker believes health advice changes too often to follow.`],speakers:[{answer:5,quote:`I fill a large bottle every morning`,explanationRu:`Количество воды контролируется с помощью бутылки с отметками.`,text:`I often reached the evening with a headache and realised I had hardly drunk anything. I fill a large bottle every morning, and the marks on its side show whether I am on schedule.`},{answer:3,quote:`I breathe in slowly for four counts`,explanationRu:`При тревоге используется конкретная техника медленного дыхания.`,text:`Before presentations my heart used to race and I could not think clearly. I breathe in slowly for four counts and breathe out for six, which helps my body calm down.`},{answer:1,quote:`my friends are waiting for me at the sports centre`,explanationRu:`Совместные тренировки помогают не пропускать занятия.`,text:`I easily invent excuses when I plan to exercise alone. If my friends are waiting for me at the sports centre, I always go, and we encourage one another through the difficult parts.`},{answer:0,quote:`I leave my phone outside the bedroom`,explanationRu:`Качество сна улучшилось после отказа от телефона перед сном.`,text:`I used to watch short videos until midnight and then felt exhausted at school. Now I leave my phone outside the bedroom and read for twenty minutes before switching off the light.`},{answer:2,quote:`I cook several lunches on Sunday`,explanationRu:`Полезные обеды готовятся заранее на всю учебную неделю.`,text:`When I am hungry after lessons, buying chips seems like the easiest choice. Instead, I cook several lunches on Sunday and keep them in boxes ready to take to school.`},{answer:4,quote:`I walk there rather than wait for a bus`,explanationRu:`Короткие поездки заменяются пешими прогулками.`,text:`The shops and library are less than twenty minutes from my home. I walk there rather than wait for a bus, which gives me regular movement without needing extra gym time.`}]}),s({slug:`career-choices`,title:`Choosing a future career`,topic:`work and careers`,cefr:`B2`,statements:[`The speaker values a job that benefits society.`,`The speaker wants a career with opportunities to travel.`,`The speaker changed plans after gaining work experience.`,`The speaker is attracted by financial security.`,`The speaker hopes to combine creativity with technology.`,`The speaker is continuing a family profession.`,`The speaker has not considered any career options yet.`],speakers:[{answer:2,quote:`A week in a real kitchen changed my mind`,explanationRu:`Практика показала реальность профессии и заставила изменить выбор.`,text:`I imagined becoming a chef because I enjoy cooking at home. A week in a real kitchen changed my mind: the pace and heat were exhausting, so I am now exploring food science instead.`},{answer:5,quote:`Both my parents design buildings`,explanationRu:`Выбор архитектуры продолжает профессиональную традицию семьи.`,text:`Both my parents design buildings, and I grew up looking at their plans. They never pressured me, but architecture feels natural because it joins the art and mathematics I already love.`},{answer:0,quote:`I want my daily work to improve somebody’s life`,explanationRu:`Главный критерий будущей работы — реальная польза для других людей.`,text:`A high salary would be pleasant, but it would not be enough on its own. I want my daily work to improve somebody’s life, which is why occupational therapy interests me.`},{answer:4,quote:`Interactive design lets me code and tell stories`,explanationRu:`Профессия должна соединить программирование и творческое повествование.`,text:`People tell me to choose either computing or art, but I do not see why. Interactive design lets me code and tell stories, so I can use both sides of my interests.`},{answer:3,quote:`A reliable income matters greatly to me`,explanationRu:`Стабильный заработок важен из-за финансового опыта семьи.`,text:`My parents have both experienced periods without work, and that uncertainty was difficult. A reliable income matters greatly to me, so I am considering careers with a steady demand for staff.`},{answer:1,quote:`I would like projects in several countries`,explanationRu:`Говорящий рассчитывает работать в разных странах и культурах.`,text:`I become restless if I stay in one place for too long. As an environmental engineer, I would like projects in several countries and the chance to work with different communities.`}]}),s({slug:`family-traditions`,title:`Traditions in my family`,topic:`family`,cefr:`B1`,statements:[`The speaker’s family records stories told by older relatives.`,`The speaker’s family cooks one special meal together.`,`The speaker’s family competes in games during celebrations.`,`The speaker’s family takes the same photograph every year.`,`The speaker’s family gives handmade presents.`,`The speaker’s family spends one day without phones.`,`The speaker would like all family traditions to disappear.`],speakers:[{answer:3,quote:`we stand by the same apple tree for a photograph`,explanationRu:`Ежегодно семья повторяет фотографию в одном и том же месте.`,text:`On the first day of summer, we stand by the same apple tree for a photograph. Looking through the pictures shows how the children grow and how the garden changes.`},{answer:0,quote:`We save my grandfather’s memories as audio files`,explanationRu:`Истории старшего родственника специально записываются и сохраняются.`,text:`My grandfather knows wonderful stories about the town before we were born. We save my grandfather’s memories as audio files, and younger cousins add questions for the next recording.`},{answer:5,quote:`Every second Sunday all phones go into a drawer`,explanationRu:`Семья регулярно проводит день без телефонов и других экранов.`,text:`Every second Sunday all phones go into a drawer until the evening. At first everyone complained, but now we play outside, talk longer and notice how quickly the day passes.`},{answer:1,quote:`Each person is responsible for one part of the meal`,explanationRu:`Особое семейное блюдо готовится совместно с распределением задач.`,text:`For my grandmother’s birthday we make a huge vegetable pie from her old recipe. Each person is responsible for one part of the meal, even the youngest children.`},{answer:4,quote:`we make every birthday present ourselves`,explanationRu:`Подарки не покупают, а создают собственными руками.`,text:`Our rule is that we make every birthday present ourselves. The results are not always perfect, but a knitted scarf or painted box carries more personal meaning than something from a shop.`},{answer:2,quote:`the adults and children form mixed teams`,explanationRu:`На празднике родственники соревнуются в смешанных командах.`,text:`After our winter dinner, the adults and children form mixed teams for a quiz and silly races. Nobody cares much about the prize, but everybody wants to beat last year’s winners.`}]}),s({slug:`food-stories`,title:`What food means to me`,topic:`food`,cefr:`B1`,statements:[`The speaker learned to cook because of a dietary need.`,`The speaker connects a dish with childhood memories.`,`The speaker enjoys inventing recipes from leftovers.`,`The speaker prefers street food to formal restaurants.`,`The speaker grows interested in other cultures through food.`,`The speaker finds cooking a useful way to relax.`,`The speaker refuses to taste unfamiliar dishes.`],speakers:[{answer:1,quote:`the smell takes me straight back to my grandmother’s kitchen`,explanationRu:`Знакомый запах блюда вызывает воспоминания о детстве у бабушки.`,text:`Whenever I bake bread with caraway seeds, the smell takes me straight back to my grandmother’s kitchen. She let me shape tiny loaves while she prepared the family dinner.`},{answer:3,quote:`The best meals often come from a small market stall`,explanationRu:`Он предпочитает простую уличную еду официальным ресторанам.`,text:`White tablecloths and long menus make me uncomfortable. The best meals often come from a small market stall, where you can watch the cook and eat beside local people.`},{answer:0,quote:`I had to learn how to prepare safe meals`,explanationRu:`Готовить пришлось из-за обнаруженной пищевой аллергии.`,text:`After doctors discovered my nut allergy, ready-made food became difficult to trust. I had to learn how to prepare safe meals, and soon I became more confident than before.`},{answer:5,quote:`Chopping vegetables helps me forget a difficult day`,explanationRu:`Процесс приготовления еды используется для снятия напряжения.`,text:`Some people relax by watching television, but I need to do something with my hands. Chopping vegetables helps me forget a difficult day, and the finished soup is an extra reward.`},{answer:4,quote:`I started reading about the country behind it`,explanationRu:`Незнакомое блюдо стало поводом узнать больше о другой стране.`,text:`A neighbour once gave me a Korean rice dish I had never tried. I enjoyed it so much that I started reading about the country behind it, including its holidays and family customs.`},{answer:2,quote:`I treat the fridge like a puzzle`,explanationRu:`Остатки продуктов превращаются в новые блюда без строгого рецепта.`,text:`Throwing usable food away seems wasteful, so I treat the fridge like a puzzle. A little rice, two vegetables and yesterday’s chicken can become a completely new meal.`}]}),s({slug:`sport-motivation`,title:`Why I keep doing sport`,topic:`sport`,cefr:`B2`,statements:[`The speaker enjoys measuring personal improvement.`,`The speaker uses sport to meet people in a new place.`,`The speaker prefers activities without competition.`,`The speaker was encouraged by a professional athlete.`,`The speaker returned to sport after an injury.`,`The speaker trains for a charity event.`,`The speaker only exercises when school requires it.`],speakers:[{answer:1,quote:`Joining the local volleyball club gave me an instant group of friends`,explanationRu:`Спортивный клуб помог быстро познакомиться с людьми после переезда.`,text:`Moving to a new town was lonely because I knew nobody at school. Joining the local volleyball club gave me an instant group of friends, and we now meet outside training too.`},{answer:4,quote:`My physiotherapist helped me begin again slowly`,explanationRu:`После травмы возвращение происходило постепенно под контролем специалиста.`,text:`A knee injury kept me away from running for almost a year. My physiotherapist helped me begin again slowly, and completing my first five kilometres felt better than any medal.`},{answer:0,quote:`I compare my times with my own previous results`,explanationRu:`Мотивацией служит личный прогресс, а не сравнение с другими.`,text:`Winning against other swimmers is not what keeps me interested. I compare my times with my own previous results, and even a small improvement shows that training is working.`},{answer:2,quote:`there is no score and nobody loses`,explanationRu:`Нравится физическая активность без победителей и соревнования.`,text:`Competitive games make me nervous rather than excited. I prefer climbing with friends because there is no score and nobody loses; we simply help one another reach the top.`},{answer:5,quote:`Every kilometre brings in donations for the children’s hospital`,explanationRu:`Тренировки связаны со сбором средств для больницы.`,text:`I have entered a long cycle ride in September. Every kilometre brings in donations for the children’s hospital, so remembering the cause helps me train on rainy mornings.`},{answer:3,quote:`she spoke honestly about failing before she succeeded`,explanationRu:`История спортсменки о неудачах вдохновила продолжить занятия.`,text:`I nearly left athletics after losing several races. Then a national runner visited our club, and she spoke honestly about failing before she succeeded, which changed my attitude.`}]}),s({slug:`arts-and-culture`,title:`My connection with the arts`,topic:`culture and arts`,cefr:`B2`,statements:[`The speaker performs despite feeling nervous on stage.`,`The speaker prefers art that tells an everyday story.`,`The speaker discovered an art form through a school project.`,`The speaker volunteers at a cultural event.`,`The speaker uses art to express feelings that are hard to say.`,`The speaker enjoys restoring old objects.`,`The speaker believes museums should never use technology.`],speakers:[{answer:2,quote:`Our history teacher asked us to make a short documentary`,explanationRu:`Интерес к документальному кино появился благодаря школьному заданию.`,text:`Our history teacher asked us to make a short documentary about a local factory. Learning to combine interviews, pictures and music was so absorbing that I have continued filming.`},{answer:5,quote:`I carefully remove the dirt and repair the wooden frames`,explanationRu:`Увлечение состоит в бережном восстановлении старых предметов.`,text:`At weekend markets I search for damaged clocks and picture frames. I carefully remove the dirt and repair the wooden frames, while keeping the signs that show their age.`},{answer:0,quote:`My hands shake before every performance`,explanationRu:`Волнение перед сценой остаётся, но не мешает продолжать выступать.`,text:`My hands shake before every performance, even when I know the music perfectly. The fear disappears after the first minute, and sharing a song with an audience becomes worth it.`},{answer:4,quote:`A sketch can show emotions I cannot explain aloud`,explanationRu:`Рисование помогает передать чувства, которые трудно назвать словами.`,text:`Talking about strong feelings is difficult for me. A sketch can show emotions I cannot explain aloud, so my notebook has become a private record of important days.`},{answer:3,quote:`I guide visitors between the small theatre venues`,explanationRu:`Она добровольно помогает гостям городского театрального фестиваля.`,text:`Our town holds a theatre festival every spring. I guide visitors between the small theatre venues, answer practical questions and sometimes get to watch rehearsals from the back.`},{answer:1,quote:`I remember paintings of ordinary kitchens and streets`,explanationRu:`Больше всего впечатляет искусство о знакомой повседневной жизни.`,text:`Grand historical scenes are impressive, but I remember paintings of ordinary kitchens and streets. They make me wonder about the quiet lives of people who were rarely written about.`}]}),s({slug:`smart-shopping`,title:`How I decide what to buy`,topic:`shopping and consumer choices`,cefr:`B1`,statements:[`The speaker compares prices online before visiting a shop.`,`The speaker buys second-hand items to save resources.`,`The speaker waits before making an unplanned purchase.`,`The speaker pays more for products made fairly.`,`The speaker chooses quality over the lowest price.`,`The speaker shares rarely used items with neighbours.`,`The speaker follows every recommendation from online influencers.`],speakers:[{answer:2,quote:`I put it on a forty-eight-hour list`,explanationRu:`Незапланированная покупка откладывается на двое суток для проверки необходимости.`,text:`Bright displays can make almost anything seem necessary. If an item was not in my plan, I put it on a forty-eight-hour list; usually the wish disappears before the time is over.`},{answer:4,quote:`I would rather buy one strong pair that lasts`,explanationRu:`Долговечность для него важнее самой низкой цены.`,text:`Cheap shoes used to wear out after a few months, so they were not truly cheap. I would rather buy one strong pair that lasts, even if it costs more at first.`},{answer:5,quote:`Our building has a cupboard for tools`,explanationRu:`Редко используемые вещи хранятся совместно и доступны соседям.`,text:`Most people need a drill for only a few minutes each year. Our building has a cupboard for tools, folding chairs and other rarely used objects that neighbours can borrow.`},{answer:0,quote:`I check several websites for the normal price`,explanationRu:`Цены сравниваются заранее, чтобы распознать ненастоящую скидку.`,text:`A large sale sign does not always mean a real bargain. I check several websites for the normal price before going to the shop, including the cost of delivery.`},{answer:3,quote:`I choose brands that publish where and how their goods are produced`,explanationRu:`Покупатель готов платить больше за прозрачные и справедливые условия производства.`,text:`Very low prices can hide poor working conditions. When I can afford it, I choose brands that publish where and how their goods are produced and pay workers fairly.`},{answer:1,quote:`Second-hand furniture prevents useful materials from being wasted`,explanationRu:`Подержанная мебель выбирается ради экономии материалов, а не только денег.`,text:`My room contains a desk from a charity shop and a chair found online. Second-hand furniture prevents useful materials from being wasted, and older pieces often have more character.`}]}),s({slug:`home-and-neighbours`,title:`Making a place feel like home`,topic:`housing and neighbourhood`,cefr:`B1`,statements:[`The speaker has created a study area in a small home.`,`The speaker got to know neighbours through a shared project.`,`The speaker values living close to public services.`,`The speaker misses the quiet of a former home.`,`The speaker prefers renting because it offers freedom.`,`The speaker has made a room personal without spending much.`,`The speaker wants to live completely alone in the countryside.`],speakers:[{answer:1,quote:`We turned an empty corner into a shared garden`,explanationRu:`Совместный сад стал причиной знакомства соседей друг с другом.`,text:`For years, people in our building only nodded in the lift. We turned an empty corner into a shared garden, and planning it together finally taught us one another’s names.`},{answer:3,quote:`I still notice the traffic at night`,explanationRu:`После переезда ему не хватает ночной тишины прежнего дома.`,text:`Our new flat is convenient, but I grew up in a village where evenings were silent. I still notice the traffic at night and sometimes miss hearing only wind outside.`},{answer:5,quote:`Photographs and fabric transformed the plain walls`,explanationRu:`Комната стала индивидуальной благодаря недорогому декору.`,text:`The rented room looked cold when I arrived, and painting was not allowed. Photographs and fabric transformed the plain walls, while old boxes became shelves at almost no cost.`},{answer:2,quote:`The library, clinic and sports centre are all within walking distance`,explanationRu:`Главным преимуществом района является близость важных услуг.`,text:`I do not need a car in this neighbourhood. The library, clinic and sports centre are all within walking distance, and buses run frequently to the city centre.`},{answer:0,quote:`A folding desk fits beside my wardrobe`,explanationRu:`Для занятий найдено компактное отдельное место даже в маленькой квартире.`,text:`Sharing a small flat made homework difficult at the kitchen table. A folding desk fits beside my wardrobe, giving me a clear study place that disappears when I finish.`},{answer:4,quote:`Renting allows me to move when a new opportunity appears`,explanationRu:`Аренда ценится за возможность легко сменить место проживания.`,text:`Buying a home might make sense later, but I do not know where my career will lead. Renting allows me to move when a new opportunity appears without selling property first.`}]}),s({slug:`weather-decisions`,title:`How weather changes my plans`,topic:`weather and climate`,cefr:`B2`,statements:[`The speaker uses forecasts for safety at work.`,`The speaker enjoys outdoor activity in cold weather.`,`The speaker changed a garden because summers became drier.`,`The speaker dislikes sudden changes in temperature.`,`The speaker photographs dramatic weather.`,`The speaker chooses indoor plans when rain is expected.`,`The speaker never checks a weather forecast.`],speakers:[{answer:2,quote:`We replaced thirsty plants with varieties that need less water`,explanationRu:`Сад адаптировали к более сухому лету с помощью устойчивых растений.`,text:`Our summers now bring longer dry periods than they did ten years ago. We replaced thirsty plants with varieties that need less water and collect rain from the roof.`},{answer:5,quote:`I arrange a museum or cinema visit instead`,explanationRu:`При прогнозе дождя заранее выбирается занятие в помещении.`,text:`Rain can spoil a long walk if nobody has suitable clothes. When the forecast looks wet, I arrange a museum or cinema visit instead, so the day still feels special.`},{answer:0,quote:`Strong wind can make lifting equipment dangerous`,explanationRu:`Прогноз нужен для предотвращения опасных работ на строительной площадке.`,text:`I supervise work on construction sites, where weather is more than a conversation topic. Strong wind can make lifting equipment dangerous, so I check detailed forecasts before planning each day.`},{answer:4,quote:`Storm clouds create extraordinary shapes and colours`,explanationRu:`Необычные облака и свет во время непогоды становятся объектом фотографии.`,text:`Most people hurry indoors when a storm approaches, but I take my camera to a safe viewpoint. Storm clouds create extraordinary shapes and colours that disappear within minutes.`},{answer:1,quote:`frost makes the forest feel brighter and quieter`,explanationRu:`Холод и мороз не мешают, а делают прогулку привлекательнее.`,text:`My friends stop hiking as soon as winter begins. I love it because frost makes the forest feel brighter and quieter, provided that I wear layers and carry a warm drink.`},{answer:3,quote:`A warm afternoon followed by freezing rain gives me headaches`,explanationRu:`Резкие температурные перепады вызывают плохое самочувствие.`,text:`I can cope with steady heat or steady cold, but rapid changes are difficult. A warm afternoon followed by freezing rain gives me headaches and makes choosing clothes impossible.`}]}),s({slug:`helping-others`,title:`Why I volunteer`,topic:`society and volunteering`,cefr:`B2`,statements:[`The speaker volunteers to gain experience for a career.`,`The speaker helps people use digital services.`,`The speaker supports an environmental project.`,`The speaker discovered an unexpected personal strength.`,`The speaker contributes remotely from home.`,`The speaker began volunteering after receiving help.`,`The speaker thinks volunteers should replace paid professionals.`],speakers:[{answer:5,quote:`I promised myself I would return the kindness`,explanationRu:`Помощь другим стала ответом на поддержку, полученную собственной семьёй.`,text:`When my family first moved here, volunteers helped us understand local services. I promised myself I would return the kindness, so now I welcome other new families.`},{answer:1,quote:`I show older residents how to book appointments online`,explanationRu:`Волонтёр обучает пожилых людей пользоваться цифровыми государственными услугами.`,text:`Many necessary services have moved online, but not everyone feels confident using them. I show older residents how to book appointments online without taking control of their private accounts.`},{answer:4,quote:`I translate short information pages from my bedroom`,explanationRu:`Удалённая помощь выполняется дома через перевод материалов.`,text:`My health makes regular travel difficult, yet I still wanted to contribute. I translate short information pages from my bedroom for a charity that supports international students.`},{answer:2,quote:`we measure plastic waste along the river`,explanationRu:`Работа связана с исследованием и сокращением загрязнения реки.`,text:`Once a month, we measure plastic waste along the river and record where it collects. The data helps the council place bins and plan clean-up days more effectively.`},{answer:0,quote:`It gives me supervised contact with patients`,explanationRu:`Волонтёрство даёт практический опыт для будущей медицинской профессии.`,text:`I am considering a career in nursing, but I wanted to understand hospital life first. It gives me supervised contact with patients while trained staff remain responsible for medical care.`},{answer:3,quote:`I discovered that I can stay calm in confusing situations`,explanationRu:`Во время помощи людям он неожиданно обнаружил способность сохранять спокойствие.`,text:`I expected volunteering at public events to improve my communication. More importantly, I discovered that I can stay calm in confusing situations and help others find a practical solution.`}]}),s({slug:`news-habits`,title:`How I follow the news`,topic:`media and news`,cefr:`B2`,statements:[`The speaker checks a story through several sources.`,`The speaker avoids news immediately before sleep.`,`The speaker prefers local reporting to national headlines.`,`The speaker listens to news while doing another activity.`,`The speaker discusses current events with family members.`,`The speaker follows one specialist topic in depth.`,`The speaker shares headlines without opening the articles.`],speakers:[{answer:3,quote:`I listen to a daily news podcast while making breakfast`,explanationRu:`Новости воспринимаются в аудиоформате одновременно с утренними делами.`,text:`I rarely have time to sit and read in the morning. I listen to a daily news podcast while making breakfast, then save any complicated story to examine later.`},{answer:0,quote:`I compare how at least three reliable organisations report it`,explanationRu:`Сомнительная история проверяется по нескольким надёжным источникам.`,text:`A dramatic headline can spread before the facts are clear. If a story matters, I compare how at least three reliable organisations report it and look for the original evidence.`},{answer:5,quote:`I follow climate policy in much greater detail`,explanationRu:`Одна специальная тема изучается глубже общего новостного потока.`,text:`I read a general summary each day, but I follow climate policy in much greater detail. Specialist newsletters explain the science and decisions that short reports often leave out.`},{answer:2,quote:`reports about our streets affect choices I can actually make`,explanationRu:`Местные новости важнее, потому что напрямую влияют на повседневные решения.`,text:`National politics is important, but reports about our streets affect choices I can actually make. The local paper covers transport changes, school meetings and small businesses.`},{answer:1,quote:`My phone stays outside the bedroom after nine`,explanationRu:`Поздние новости исключены, чтобы тревожные темы не нарушали сон.`,text:`Reading upsetting updates late at night made it difficult to sleep. My phone stays outside the bedroom after nine, and anything important can wait until the morning.`},{answer:4,quote:`At dinner we each bring one story to discuss`,explanationRu:`Члены семьи регулярно обсуждают выбранные новостные материалы за ужином.`,text:`My parents and I do not always agree about current events. At dinner we each bring one story to discuss, and everyone must explain why their source deserves trust.`}]}),s({slug:`science-curiosity`,title:`What makes science exciting`,topic:`science`,cefr:`B2`,statements:[`The speaker enjoys experiments with visible results.`,`The speaker is interested in unanswered questions about space.`,`The speaker studies how science affects public decisions.`,`The speaker was inspired by a scientist’s personal story.`,`The speaker likes collecting and classifying natural objects.`,`The speaker uses citizen-science software at home.`,`The speaker thinks scientific mistakes should be hidden.`],speakers:[{answer:1,quote:`every answer about the universe seems to create two new questions`,explanationRu:`Интерес к космосу поддерживают нерешённые вопросы, а не готовые факты.`,text:`I love astronomy because every answer about the universe seems to create two new questions. Dark matter is especially fascinating because scientists can observe its effects without seeing it directly.`},{answer:4,quote:`I label each stone with its location and likely type`,explanationRu:`Найденные природные объекты систематически подписываются и классифицируются.`,text:`Walks become more interesting when I search for unusual rocks. At home, I label each stone with its location and likely type, then compare my guess with a field guide.`},{answer:5,quote:`My laptop helps researchers identify changes in distant stars`,explanationRu:`Домашний компьютер используется для участия в настоящем научном проекте.`,text:`You do not need a laboratory to contribute to research. My laptop helps researchers identify changes in distant stars by letting me classify telescope images through a citizen-science website.`},{answer:0,quote:`A colour change or sudden crystal growth makes the idea memorable`,explanationRu:`Нравятся опыты, где научный процесс можно увидеть непосредственно.`,text:`Equations make more sense after I observe what they describe. A colour change or sudden crystal growth makes the idea memorable, even when the theory behind it is difficult.`},{answer:3,quote:`She continued her research after many laboratories rejected her`,explanationRu:`Настойчивость учёной после отказов стала личным источником вдохновения.`,text:`A documentary about a medical researcher changed how I viewed success. She continued her research after many laboratories rejected her, and her persistence mattered as much as talent.`},{answer:2,quote:`evidence can be misunderstood when it enters a political debate`,explanationRu:`Интерес направлен на использование науки в общественных и политических решениях.`,text:`Discoveries do not stay inside laboratories. I study how evidence can be misunderstood when it enters a political debate, especially in discussions about health and the environment.`}]}),s({slug:`good-communication`,title:`Keeping relationships strong`,topic:`relationships and communication`,cefr:`B1`,statements:[`The speaker apologises without trying to defend the mistake.`,`The speaker schedules time to keep a distant friendship alive.`,`The speaker asks questions instead of making assumptions.`,`The speaker prefers solving disagreements in writing.`,`The speaker has learned to set clear personal boundaries.`,`The speaker shows care through practical help.`,`The speaker avoids every difficult conversation.`],speakers:[{answer:1,quote:`We reserve Wednesday evening for a proper call`,explanationRu:`Для дружбы на расстоянии заранее выделяется регулярное время.`,text:`My closest friend moved abroad, and random messages were not enough. We reserve Wednesday evening for a proper call, even if one of us only has ordinary news.`},{answer:5,quote:`I repair things or bring food when someone is busy`,explanationRu:`Забота выражается конкретными делами, а не длинными разговорами.`,text:`I am not very good at emotional speeches, but my friends know I care. I repair things or bring food when someone is busy, which is my natural way of supporting them.`},{answer:2,quote:`I now ask what the person meant`,explanationRu:`Вместо поспешного вывода говорящая уточняет смысл слов собеседника.`,text:`I once became angry about a message that I had completely misunderstood. I now ask what the person meant before deciding they are rude, especially when we communicate online.`},{answer:4,quote:`saying no does not make me unkind`,explanationRu:`Она учится отказывать и защищать своё время без чувства вины.`,text:`I used to agree to every request and then feel exhausted. I have learned that saying no does not make me unkind, and I can offer another time when I am genuinely free.`},{answer:0,quote:`I say clearly what I did wrong`,explanationRu:`Извинение содержит прямое признание ошибки без оправданий.`,text:`Adding a long excuse can make an apology sound dishonest. I say clearly what I did wrong, recognise how it affected the other person and ask how to repair the situation.`},{answer:3,quote:`Writing gives both of us time to choose calmer words`,explanationRu:`Письменный формат помогает спокойно обсудить конфликт.`,text:`During an argument I speak too quickly and regret it later. Writing gives both of us time to choose calmer words, although we still meet afterwards to make sure everything is understood.`}]}),s({slug:`outdoor-discoveries`,title:`What I find outdoors`,topic:`nature`,cefr:`B1`,statements:[`The speaker watches wildlife without disturbing it.`,`The speaker enjoys navigating without a phone.`,`The speaker collects litter during walks.`,`The speaker prefers short local adventures.`,`The speaker keeps a written record of seasonal changes.`,`The speaker overcame fear through an outdoor activity.`,`The speaker wants nature reserves to become amusement parks.`],speakers:[{answer:4,quote:`I note the first flowers, migrating birds and changing leaves`,explanationRu:`Сезонные наблюдения регулярно записываются в дневник.`,text:`I visit the same woodland path throughout the year. In a small notebook, I note the first flowers, migrating birds and changing leaves, so gradual seasonal changes become visible.`},{answer:1,quote:`a paper map makes me notice the shape of the land`,explanationRu:`Ориентирование по бумажной карте помогает внимательнее видеть местность.`,text:`Digital directions are useful in cities, but a paper map makes me notice the shape of the land. Finding a route with a compass also gives me a satisfying sense of independence.`},{answer:3,quote:`Most of my favourite trips are within an hour of home`,explanationRu:`Для приключений выбираются близкие места без дальней поездки.`,text:`People often think adventure requires an expensive journey. Most of my favourite trips are within an hour of home: a sunrise by the lake or an unfamiliar village path.`},{answer:0,quote:`I remain on the path and use a long camera lens`,explanationRu:`Животных наблюдают на расстоянии, не сходя с маршрута.`,text:`Seeing a deer is exciting, but its safety matters more than my photograph. I remain on the path and use a long camera lens rather than moving closer or offering food.`},{answer:5,quote:`Completing the high rope course changed that belief`,explanationRu:`Высотная трасса помогла убедиться, что страх можно контролировать.`,text:`For years I believed that being afraid of heights could never change. Completing the high rope course changed that belief because each small platform made the next one possible.`},{answer:2,quote:`I carry a separate bag for bottles and wrappers`,explanationRu:`Во время прогулки мусор собирается в специальный пакет.`,text:`It is frustrating to find rubbish beside a beautiful river. I carry a separate bag for bottles and wrappers on every walk, and friends have started doing the same.`}]}),s({slug:`getting-around`,title:`My daily journey`,topic:`transport`,cefr:`B1`,statements:[`The speaker cycles because it makes journey times predictable.`,`The speaker uses travel time for studying.`,`The speaker shares car journeys with colleagues.`,`The speaker walks part of the route for exercise.`,`The speaker changed transport because of cost.`,`The speaker enjoys observing people on public transport.`,`The speaker wants every city centre road to be wider.`],speakers:[{answer:4,quote:`The monthly fuel bill became impossible to ignore`,explanationRu:`Рост расходов заставил отказаться от ежедневной поездки на машине.`,text:`I drove to college even though a bus stopped near my home. The monthly fuel bill became impossible to ignore, so I bought a student bus pass and now spend far less.`},{answer:1,quote:`I review vocabulary during the forty-minute train ride`,explanationRu:`Долгая поездка используется для регулярного повторения слов.`,text:`My commute looks long on a map, but it is not wasted time. I review vocabulary during the forty-minute train ride and usually finish one homework task before arriving.`},{answer:0,quote:`Traffic jams no longer decide when I arrive`,explanationRu:`Велосипед даёт стабильное время в пути независимо от пробок.`,text:`The bicycle route takes almost exactly twenty-five minutes every morning. Traffic jams no longer decide when I arrive, and secure parking at work removes my last concern.`},{answer:5,quote:`Short journeys reveal tiny pieces of other people’s lives`,explanationRu:`Ему интересно наблюдать повседневное поведение пассажиров.`,text:`On the underground I notice what passengers read, carry and talk about. Short journeys reveal tiny pieces of other people’s lives, and sometimes they inspire characters for my stories.`},{answer:2,quote:`Three colleagues take turns driving each week`,explanationRu:`Сотрудники организовали совместные поездки и меняют водителя.`,text:`There is no direct public transport to our office outside town. Three colleagues take turns driving each week, which reduces both our costs and the number of cars.`},{answer:3,quote:`I leave the bus two stops early`,explanationRu:`Часть маршрута намеренно проходится пешком ради движения.`,text:`A desk job gives me very little movement during the day. I leave the bus two stops early and walk through the park, adding exercise without changing my evening plans.`}]}),s({slug:`personal-growth`,title:`A skill I am developing`,topic:`personal development`,cefr:`B2`,statements:[`The speaker is becoming more confident about public speaking.`,`The speaker is learning to manage money independently.`,`The speaker is practising patience through a slow activity.`,`The speaker is reducing perfectionism by finishing small projects.`,`The speaker is learning to ask for constructive feedback.`,`The speaker is improving at making difficult decisions.`,`The speaker believes abilities cannot change after childhood.`],speakers:[{answer:3,quote:`I finish one small project before improving it`,explanationRu:`Маленькие завершённые проекты помогают отказаться от стремления к идеалу.`,text:`I used to abandon drawings because the first attempt looked wrong. Now I finish one small project before improving it, which teaches me that completed work can develop later.`},{answer:1,quote:`I divide my income into spending, saving and future costs`,explanationRu:`Личный бюджет распределяется по трём понятным категориям.`,text:`My first part-time salary disappeared in a week because I had no plan. I divide my income into spending, saving and future costs, and check the totals every Sunday.`},{answer:5,quote:`I list what matters and set a deadline`,explanationRu:`Сложные решения принимаются по критериям и в ограниченный срок.`,text:`When two choices seem equally good, I can worry for days. I list what matters and set a deadline, accepting that no decision can guarantee a perfect result.`},{answer:0,quote:`Each short presentation makes the next one less frightening`,explanationRu:`Уверенность растёт постепенно благодаря частым небольшим выступлениям.`,text:`Speaking to a large group still makes me nervous, so I volunteer for brief class reports. Each short presentation makes the next one less frightening and gives me evidence of progress.`},{answer:2,quote:`The garden cannot be hurried`,explanationRu:`Уход за растениями развивает терпение, потому что результат требует времени.`,text:`I like fast results and become frustrated when progress is invisible. The garden cannot be hurried, so growing vegetables teaches me to keep caring for something before any reward appears.`},{answer:4,quote:`I ask for one specific suggestion`,explanationRu:`Обратная связь запрашивается в конкретной форме, чтобы её было легче применить.`,text:`General criticism used to feel personal and useless. Now I ask for one specific suggestion after each piece of work, then decide how to apply it in the next version.`}]})],u=[c({slug:`science-open-day`,title:`Science club open day`,topic:`education`,cefr:`B1`,voices:[`female_1`,`male_1`],dialogue:[`Have you finished the plan for the science club open day? It is next Saturday, and the doors will open at ten in the morning.`,`Almost. The chemistry laboratory is being repaired, so we will use room 204 for the robotics display instead of the lab.`,`Visitors must register online by Wednesday. We cannot register people at the door because the school needs the final numbers in advance.`,`That makes sense. Two teachers will supervise the room, and Maya will demonstrate the solar-powered car that our team built this term.`,`What about food? I thought we had to buy snacks from the café across the road.`,`No, several parents have offered to bring sandwiches and fruit. We only need to provide water and cups for everyone.`],items:[{statement:`The open day will take place on Saturday.`,answer:`true`,quote:`It is next Saturday`,explanationRu:`День мероприятия назван прямо: следующая суббота.`},{statement:`The robotics display will be held in the chemistry laboratory.`,answer:`false`,quote:`we will use room 204 for the robotics display instead of the lab`,explanationRu:`Роботов покажут в кабинете 204, а не в лаборатории.`},{statement:`Visitors can register when they arrive at the school.`,answer:`false`,quote:`We cannot register people at the door`,explanationRu:`Регистрация на месте прямо исключена; она проходит онлайн заранее.`},{statement:`The chemistry laboratory is temporarily unavailable.`,answer:`true`,quote:`The chemistry laboratory is being repaired`,explanationRu:`Лаборатория недоступна, потому что в ней идёт ремонт.`},{statement:`The solar car has won a national competition.`,answer:`not_stated`,quote:`the solar-powered car that our team built this term`,explanationRu:`Сказано только, что команда построила машину; о победе сведений нет.`},{statement:`Some parents will prepare food for visitors.`,answer:`true`,quote:`several parents have offered to bring sandwiches and fruit`,explanationRu:`Родители предложили принести бутерброды и фрукты.`},{statement:`The open day will finish at four o’clock.`,answer:`not_stated`,quote:`the doors will open at ten in the morning`,explanationRu:`Время открытия известно, но время окончания не называется.`}]}),c({slug:`coastal-weekend`,title:`A weekend by the coast`,topic:`travel`,cefr:`B1`,voices:[`male_2`,`female_2`],dialogue:[`Our train to Seabrook leaves at 7:40 on Friday. I nearly booked the coach, but the train arrives two hours earlier.`,`Good choice. The guest house is only a ten-minute walk from the station, and breakfast is included in the room price.`,`I reserved a boat trip for Friday evening, although the company has just cancelled it because strong winds are expected.`,`Then we could visit the old lighthouse. It stays open until six, and the path along the cliffs starts beside it.`,`The forecast says Saturday morning should be bright, but clouds may arrive later. I will pack a waterproof jacket anyway.`,`Fine. Shall we hire bicycles on Sunday? Let us decide there after we see how tired we are from the cliff walk.`],items:[{statement:`The travellers will go to Seabrook by train.`,answer:`true`,quote:`Our train to Seabrook leaves at 7:40`,explanationRu:`Они прямо обсуждают свой поезд до Сибрука.`},{statement:`The coach reaches Seabrook earlier than the train.`,answer:`false`,quote:`the train arrives two hours earlier`,explanationRu:`Поезд прибывает на два часа раньше автобуса, а не наоборот.`},{statement:`Breakfast costs extra at the guest house.`,answer:`false`,quote:`breakfast is included in the room price`,explanationRu:`Завтрак уже включён в стоимость комнаты.`},{statement:`The Friday boat trip has been cancelled.`,answer:`true`,quote:`the company has just cancelled it`,explanationRu:`Компания отменила вечернюю прогулку на лодке.`},{statement:`The lighthouse closes at six o’clock.`,answer:`true`,quote:`It stays open until six`,explanationRu:`Маяк открыт до шести часов.`},{statement:`It will rain throughout Saturday.`,answer:`false`,quote:`Saturday morning should be bright`,explanationRu:`Утро ожидается ясным, поэтому дождь весь день противоречит записи.`},{statement:`Bicycles can be hired beside the guest house.`,answer:`not_stated`,quote:`Shall we hire bicycles on Sunday?`,explanationRu:`Возможность аренды обсуждается, но местонахождение пункта проката не называется.`}]}),c({slug:`repair-cafe`,title:`Starting a repair café`,topic:`environment`,cefr:`B2`,voices:[`female_3`,`male_3`],dialogue:[`The community centre has agreed to host our first repair café on the second Sunday of every month, beginning in September.`,`Excellent. I have found volunteers who can fix small electrical devices, but nobody with enough experience of repairing bicycles yet.`,`The college mechanic may help later. For September, the website should clearly say that we accept lamps, kettles and simple clothing repairs.`,`Should visitors pay? I would prefer the service to remain free, with a box for optional donations towards replacement parts.`,`Agreed. People must book a thirty-minute slot so volunteers are not overwhelmed. We will keep two spaces for urgent walk-in repairs.`,`I will also ask visitors to stay and watch. Learning why an object failed is as important as preventing it from being thrown away.`],items:[{statement:`The repair café will run once a month.`,answer:`true`,quote:`on the second Sunday of every month`,explanationRu:`Встречи запланированы ежемесячно, во второе воскресенье.`},{statement:`A bicycle mechanic has already joined the volunteers.`,answer:`false`,quote:`nobody with enough experience of repairing bicycles yet`,explanationRu:`Опытного мастера по велосипедам пока нет.`},{statement:`The first event will accept broken kettles.`,answer:`true`,quote:`we accept lamps, kettles and simple clothing repairs`,explanationRu:`Чайники прямо перечислены среди принимаемых вещей.`},{statement:`Every visitor will have to pay a fixed repair fee.`,answer:`false`,quote:`the service to remain free`,explanationRu:`Услуга останется бесплатной; возможны лишь добровольные пожертвования.`},{statement:`Most visitors need to reserve a time slot.`,answer:`true`,quote:`People must book a thirty-minute slot`,explanationRu:`Посетители должны заранее забронировать получасовой интервал.`},{statement:`Replacement parts will be supplied by a local factory.`,answer:`not_stated`,quote:`optional donations towards replacement parts`,explanationRu:`Обсуждается оплата деталей пожертвованиями, но поставщик не назван.`},{statement:`Visitors are encouraged to observe the repair process.`,answer:`true`,quote:`ask visitors to stay and watch`,explanationRu:`Посетителям предлагают остаться и посмотреть, как проходит ремонт.`}]}),c({slug:`homework-app`,title:`Testing a homework app`,topic:`technology`,cefr:`B1`,voices:[`male_1`,`female_1`],dialogue:[`I tried the new homework app for a week. It puts tasks from every subject into one calendar and reminds me the evening before each deadline.`,`Does it complete exercises for you? Some students think that is what an intelligent study app should do.`,`No, and I am glad it does not. It only organises the work. I still solve every task myself and upload a photograph when I finish.`,`My concern is privacy. Does the app share your marks with classmates or show where you live?`,`Marks are visible only to me and my teachers. It never asks for my address, but it needs internet access to synchronise the calendar.`,`That could be difficult on the bus. I heard an offline version is planned, though the developers have not announced a release date.`],items:[{statement:`The app combines homework from different subjects.`,answer:`true`,quote:`tasks from every subject into one calendar`,explanationRu:`Задания по всем предметам собраны в одном календаре.`},{statement:`The app reminds the student one week before a deadline.`,answer:`false`,quote:`reminds me the evening before each deadline`,explanationRu:`Напоминание приходит накануне вечером, а не за неделю.`},{statement:`The app solves exercises automatically.`,answer:`false`,quote:`I still solve every task myself`,explanationRu:`Ученик выполняет каждое задание самостоятельно.`},{statement:`Classmates can see the student’s marks.`,answer:`false`,quote:`Marks are visible only to me and my teachers`,explanationRu:`Оценки доступны только ученику и учителям.`},{statement:`The app requires an internet connection to update the calendar.`,answer:`true`,quote:`it needs internet access to synchronise the calendar`,explanationRu:`Для синхронизации календаря необходим интернет.`},{statement:`The offline version will be released next month.`,answer:`not_stated`,quote:`the developers have not announced a release date`,explanationRu:`Дата выпуска офлайн-версии ещё не объявлена.`},{statement:`The student has used the app for seven days.`,answer:`true`,quote:`I tried the new homework app for a week`,explanationRu:`Неделя использования равна семи дням.`}]}),c({slug:`sleep-workshop`,title:`A school sleep workshop`,topic:`health`,cefr:`B2`,voices:[`female_2`,`male_2`],dialogue:[`The school nurse is giving a sleep workshop on Tuesday because many final-year students say they feel exhausted before lessons.`,`Will she simply tell everyone to go to bed earlier? My problem is that I lie awake even when I turn the light off at ten.`,`The session is more practical than that. We will examine evening routines, caffeine and bedroom temperature, then create a personal two-week experiment.`,`I stopped drinking coffee after lunch, but I still use my phone in bed. Is there reliable evidence that screens actually make a difference?`,`She will explain the research, but nobody has to hand over their phone. We record our own habits privately and share only general observations.`,`That sounds reasonable. I have football practice on Tuesday afternoon, so I hope the workshop starts after four. The notice does not give the time.`],items:[{statement:`The workshop is aimed partly at tired final-year students.`,answer:`true`,quote:`many final-year students say they feel exhausted`,explanationRu:`Поводом стали жалобы выпускников на усталость.`},{statement:`The workshop will only advise students to sleep earlier.`,answer:`false`,quote:`The session is more practical than that`,explanationRu:`Программа шире простого совета лечь раньше.`},{statement:`Students will design a two-week experiment.`,answer:`true`,quote:`create a personal two-week experiment`,explanationRu:`Каждый составит личный эксперимент на две недели.`},{statement:`One speaker no longer drinks coffee in the evening.`,answer:`true`,quote:`I stopped drinking coffee after lunch`,explanationRu:`После обеда говорящий больше не пьёт кофе, значит и вечером тоже.`},{statement:`Students must give their phones to the nurse.`,answer:`false`,quote:`nobody has to hand over their phone`,explanationRu:`Телефон сдавать медсестре не требуется.`},{statement:`Individual sleep records will be shown to the whole class.`,answer:`false`,quote:`share only general observations`,explanationRu:`Делиться будут только общими наблюдениями, не личными записями.`},{statement:`The workshop will begin after four o’clock.`,answer:`not_stated`,quote:`The notice does not give the time`,explanationRu:`Желаемое время названо, но фактическое начало неизвестно.`}]}),c({slug:`library-summer-job`,title:`A summer job at the library`,topic:`work`,cefr:`B1`,voices:[`male_3`,`female_3`],dialogue:[`I saw your message about the summer assistant job at the town library. Are applications still open?`,`Yes, until Friday at noon. The job lasts for six weeks, from the middle of July until the end of August.`,`I expected assistants to put books back on shelves, but the advert also mentions working with children.`,`Every Wednesday we run a reading club for eight- to ten-year-olds. You would prepare simple activities, while a librarian leads the session.`,`Do I need previous work experience? I helped at a school book sale, although I have never had a paid job.`,`Experience is useful but not required. Applicants must be at least sixteen and available on Saturday mornings. The exact hourly pay is discussed at interview.`],items:[{statement:`Applications close by Friday lunchtime.`,answer:`true`,quote:`until Friday at noon`,explanationRu:`Последний срок подачи заявок — полдень пятницы.`},{statement:`The position continues for eight weeks.`,answer:`false`,quote:`The job lasts for six weeks`,explanationRu:`Работа рассчитана на шесть недель, а не на восемь.`},{statement:`Assistants will lead the children’s reading club alone.`,answer:`false`,quote:`a librarian leads the session`,explanationRu:`Встречу ведёт библиотекарь, помощник лишь готовит задания.`},{statement:`The reading club meets once a week.`,answer:`true`,quote:`Every Wednesday we run a reading club`,explanationRu:`Клуб проходит каждую среду, то есть еженедельно.`},{statement:`Previous paid employment is compulsory.`,answer:`false`,quote:`Experience is useful but not required`,explanationRu:`Опыт полезен, но обязательным условием не является.`},{statement:`Applicants must be sixteen or older.`,answer:`true`,quote:`Applicants must be at least sixteen`,explanationRu:`Минимальный возраст прямо указан — шестнадцать лет.`},{statement:`The hourly wage is higher than at the local café.`,answer:`not_stated`,quote:`The exact hourly pay is discussed at interview`,explanationRu:`Ставка пока не названа и с кафе не сравнивается.`}]}),c({slug:`photography-exhibition`,title:`Preparing a photography exhibition`,topic:`culture`,cefr:`B2`,voices:[`female_1`,`male_2`],dialogue:[`The gallery accepted our exhibition proposal, but they want the theme narrowed from city life in general to the way neighbourhoods change over time.`,`That suits my photographs. I have pairs showing the same streets in winter and summer, although none of my pictures are more than three years old.`,`We can borrow older images from the local archive if we credit each photographer. Digital copies are free, but printing large versions is our responsibility.`,`I can print them at college for a reduced price. How many works can the gallery hold?`,`The curator recommends twenty-four. She also wants short captions in both English and Russian so international visitors can follow the stories.`,`Let us invite residents to the opening on the ninth of October. The gallery provides the room, but we must organise any music or refreshments ourselves.`],items:[{statement:`The exhibition will focus on changes in neighbourhoods.`,answer:`true`,quote:`the way neighbourhoods change over time`,explanationRu:`Галерея сузила тему до изменений районов со временем.`},{statement:`One speaker owns photographs taken ten years ago.`,answer:`false`,quote:`none of my pictures are more than three years old`,explanationRu:`Его собственным фотографиям не больше трёх лет.`},{statement:`Using digital archive copies will cost nothing.`,answer:`true`,quote:`Digital copies are free`,explanationRu:`Цифровые копии архива предоставляются бесплатно.`},{statement:`The gallery will pay to print all the photographs.`,answer:`false`,quote:`printing large versions is our responsibility`,explanationRu:`Печать крупных версий оплачивают организаторы, не галерея.`},{statement:`The curator suggests displaying twenty-four works.`,answer:`true`,quote:`The curator recommends twenty-four`,explanationRu:`Куратор рекомендует двадцать четыре работы.`},{statement:`Captions will be written in two languages.`,answer:`true`,quote:`captions in both English and Russian`,explanationRu:`Подписи готовятся на английском и русском языках.`},{statement:`A professional band will play at the opening.`,answer:`not_stated`,quote:`we must organise any music`,explanationRu:`Музыку предстоит организовать, но группа и её статус не указаны.`}]}),c({slug:`animal-shelter`,title:`Helping at an animal shelter`,topic:`volunteering`,cefr:`B1`,voices:[`male_1`,`female_2`],dialogue:[`The animal shelter needs volunteers during the school holiday. I thought we could help on Tuesday and Thursday afternoons.`,`I am free on Thursday, but I have a dentist appointment on Tuesday. New volunteers must first attend a safety talk on Monday evening.`,`That is fine. The email says people under eighteen can clean cages and prepare food, but only adults may walk large dogs.`,`We can spend time with the cats instead. Some are nervous around strangers, so the manager asks volunteers to sit quietly and let the animals approach.`,`Should we bring old blankets? My family has several that we no longer use.`,`Yes, blankets and unopened pet food are welcome. They do not accept homemade food because the animals follow special diets.`],items:[{statement:`Both speakers are available on Tuesday afternoon.`,answer:`false`,quote:`I have a dentist appointment on Tuesday`,explanationRu:`Один из собеседников занят у стоматолога во вторник.`},{statement:`First-time volunteers attend a safety talk.`,answer:`true`,quote:`New volunteers must first attend a safety talk`,explanationRu:`Для новых волонтёров инструктаж обязателен.`},{statement:`Teenagers are allowed to prepare animal food.`,answer:`true`,quote:`people under eighteen can clean cages and prepare food`,explanationRu:`Несовершеннолетним разрешено готовить корм.`},{statement:`Teenagers can walk the shelter’s large dogs.`,answer:`false`,quote:`only adults may walk large dogs`,explanationRu:`Крупных собак могут выгуливать только взрослые.`},{statement:`Volunteers should wait for nervous cats to come closer.`,answer:`true`,quote:`let the animals approach`,explanationRu:`Нужно спокойно ждать, пока животное подойдёт само.`},{statement:`The shelter needs exactly twelve blankets.`,answer:`not_stated`,quote:`blankets and unopened pet food are welcome`,explanationRu:`Одеяла нужны, но их точное количество не называется.`},{statement:`The shelter accepts food cooked by volunteers.`,answer:`false`,quote:`They do not accept homemade food`,explanationRu:`Домашний корм приют прямо отказывается принимать.`}]}),c({slug:`headphones-return`,title:`Returning online headphones`,topic:`shopping`,cefr:`B2`,voices:[`female_3`,`male_1`],dialogue:[`The wireless headphones I ordered arrived yesterday, but the left side loses sound whenever I move my head.`,`You can return faulty goods within thirty days. Did you keep the original box and the order confirmation?`,`I have the email confirmation, although I recycled the outer delivery box. The product box itself is still undamaged.`,`That is enough. Print the free return label, attach it to any strong parcel and take it to a collection point.`,`Could they send a replacement before receiving this pair? I need headphones for an online course starting Monday.`,`The website says replacements are dispatched after the faulty item is scanned at the collection point. It does not promise delivery by Monday.`],items:[{statement:`The headphones have a problem on the left side.`,answer:`true`,quote:`the left side loses sound`,explanationRu:`Неисправность возникает в левом наушнике.`},{statement:`The customer received the headphones a week ago.`,answer:`false`,quote:`arrived yesterday`,explanationRu:`Заказ прибыл вчера, а не неделю назад.`},{statement:`Faulty products may be returned within thirty days.`,answer:`true`,quote:`return faulty goods within thirty days`,explanationRu:`Срок возврата неисправного товара — тридцать дней.`},{statement:`The customer has thrown away every part of the packaging.`,answer:`false`,quote:`The product box itself is still undamaged`,explanationRu:`Коробка самого товара сохранилась без повреждений.`},{statement:`The return postage is free.`,answer:`true`,quote:`Print the free return label`,explanationRu:`Бесплатная возвратная этикетка означает бесплатную отправку.`},{statement:`A replacement is sent after the parcel is scanned.`,answer:`true`,quote:`dispatched after the faulty item is scanned`,explanationRu:`Замену отправляют после сканирования неисправного товара.`},{statement:`The replacement will arrive before Monday.`,answer:`not_stated`,quote:`It does not promise delivery by Monday`,explanationRu:`Магазин не гарантирует доставку к понедельнику.`}]}),c({slug:`station-cycle-parking`,title:`New cycle parking at the station`,topic:`transport`,cefr:`B1`,voices:[`male_2`,`female_1`],dialogue:[`Have you seen the new covered bicycle parking beside the east entrance of the station? It opened this morning.`,`Yes. There are sixty spaces, twice as many as the old rack, and the first twelve hours are free.`,`After that it costs one pound per day. You need the station app to open the gate, which may be difficult for visitors.`,`The ticket office can issue a temporary code to anyone without the app. Cyclists should bring their own lock because none are provided.`,`I heard there is also a repair pump and a place to charge electric bicycles.`,`The pump is already working. The charging points are installed, but they will remain switched off until the safety inspection next week.`],items:[{statement:`The bicycle parking is near the station’s east entrance.`,answer:`true`,quote:`beside the east entrance of the station`,explanationRu:`Парковка находится рядом с восточным входом.`},{statement:`The new parking area has thirty spaces.`,answer:`false`,quote:`There are sixty spaces`,explanationRu:`Предусмотрено шестьдесят мест, а не тридцать.`},{statement:`Parking is free for the first twelve hours.`,answer:`true`,quote:`the first twelve hours are free`,explanationRu:`Первые двенадцать часов оплачивать не нужно.`},{statement:`People without the app cannot enter the parking area.`,answer:`false`,quote:`The ticket office can issue a temporary code`,explanationRu:`Без приложения можно получить временный код в кассе.`},{statement:`Cyclists must use their own bicycle locks.`,answer:`true`,quote:`bring their own lock because none are provided`,explanationRu:`Замки не выдаются, поэтому нужен собственный.`},{statement:`The repair pump is not working yet.`,answer:`false`,quote:`The pump is already working`,explanationRu:`Ремонтный насос уже находится в рабочем состоянии.`},{statement:`The safety inspection will happen on Tuesday.`,answer:`not_stated`,quote:`the safety inspection next week`,explanationRu:`Указана только следующая неделя, но конкретный день не назван.`}]}),c({slug:`meteor-watch`,title:`A community meteor watch`,topic:`science`,cefr:`B2`,voices:[`female_2`,`male_3`],dialogue:[`The astronomy group is organising a meteor watch on the hill outside town next Friday, provided the sky remains clear.`,`Do we need telescopes? I have binoculars, but carrying the school telescope up the path would be difficult.`,`Meteors are easier to see with the naked eye, so telescopes are unnecessary. Bring a reclining chair, warm layers and a red-covered torch.`,`Why red? I usually use the bright torch on my phone when I walk at night.`,`White light ruins night vision for several minutes. The group will provide red film for ordinary torches, but everyone brings their own batteries.`,`The observation begins at eleven and may continue until two. If clouds force a cancellation, the organiser will post a message by eight that evening.`],items:[{statement:`The meteor watch is planned for Friday.`,answer:`true`,quote:`next Friday`,explanationRu:`Наблюдение назначено на следующую пятницу.`},{statement:`Participants must bring a telescope.`,answer:`false`,quote:`telescopes are unnecessary`,explanationRu:`Телескопы для наблюдения не нужны.`},{statement:`Warm clothing is recommended.`,answer:`true`,quote:`Bring a reclining chair, warm layers`,explanationRu:`Организаторы прямо советуют тёплую многослойную одежду.`},{statement:`The group supplies batteries for every torch.`,answer:`false`,quote:`everyone brings their own batteries`,explanationRu:`Батарейки каждый участник приносит сам.`},{statement:`The observation is scheduled to start at 11 p.m.`,answer:`true`,quote:`The observation begins at eleven`,explanationRu:`Начало наблюдения назначено на одиннадцать вечера.`},{statement:`Cancellation information will appear before nine.`,answer:`true`,quote:`post a message by eight that evening`,explanationRu:`Сообщение появится до восьми, значит и до девяти.`},{statement:`More than fifty people have registered.`,answer:`not_stated`,quote:`The astronomy group is organising a meteor watch`,explanationRu:`Организатор назван, но число зарегистрированных участников отсутствует.`}]}),c({slug:`family-reunion`,title:`Organising a family reunion`,topic:`family`,cefr:`B1`,voices:[`male_1`,`female_3`],dialogue:[`Grandma would like the family reunion to be at her house again, but thirty guests will not fit comfortably in the garden.`,`The village hall is available on the twenty-second of June. It has tables, a kitchen and space indoors if the weather changes.`,`Let us book it. Uncle Victor can cook the main meal, while each family brings either a salad or a dessert.`,`I will make a list so we do not receive ten cakes. Cousin Nina is vegetarian, and two children cannot eat nuts.`,`We should also collect old photographs for a family timeline. Grandma has albums, but she does not know the dates of every picture.`,`I can scan the photographs and ask relatives to identify people online. We have not chosen music yet, so I will add that to the next call.`],items:[{statement:`Thirty people are expected at the reunion.`,answer:`true`,quote:`thirty guests`,explanationRu:`Ожидается тридцать гостей.`},{statement:`The reunion will definitely take place in Grandma’s garden.`,answer:`false`,quote:`thirty guests will not fit comfortably in the garden`,explanationRu:`Сад признан слишком маленьким; выбирают деревенский зал.`},{statement:`The village hall has a kitchen.`,answer:`true`,quote:`It has tables, a kitchen`,explanationRu:`Кухня прямо перечислена среди удобств зала.`},{statement:`Every family will prepare the main course.`,answer:`false`,quote:`Uncle Victor can cook the main meal`,explanationRu:`Главное блюдо приготовит дядя Виктор.`},{statement:`Some children must avoid nuts.`,answer:`true`,quote:`two children cannot eat nuts`,explanationRu:`У двух детей есть ограничение на орехи.`},{statement:`All the old photographs have known dates.`,answer:`false`,quote:`she does not know the dates of every picture`,explanationRu:`Даты некоторых снимков бабушке неизвестны.`},{statement:`A jazz group will provide the music.`,answer:`not_stated`,quote:`We have not chosen music yet`,explanationRu:`Музыка ещё не выбрана, о джазовой группе данных нет.`}]}),c({slug:`local-podcast`,title:`Launching a local podcast`,topic:`media`,cefr:`B2`,voices:[`female_1`,`male_2`],dialogue:[`Our first podcast episode about local history is edited, but at forty-eight minutes it is much longer than the half-hour format we planned.`,`We could remove the general introduction and begin with the interview. The historian tells the story clearly without extra background.`,`I would keep a short introduction, then divide the interview into two episodes. That gives listeners time to send questions before part two.`,`Good idea. We should publish every other Thursday rather than weekly, because research and fact-checking take longer than recording.`,`The library has offered us its quiet meeting room for free. We need to reserve it, and we must bring our own microphones and laptop.`,`I will write music for the opening so we avoid licensing problems. We still need permission to use three archive photographs on the episode page.`],items:[{statement:`The edited first episode currently lasts forty-eight minutes.`,answer:`true`,quote:`at forty-eight minutes`,explanationRu:`Текущая продолжительность монтажа — сорок восемь минут.`},{statement:`The speakers originally planned a one-hour format.`,answer:`false`,quote:`the half-hour format we planned`,explanationRu:`Изначально планировался получасовой выпуск.`},{statement:`They decide to divide the interview into two episodes.`,answer:`true`,quote:`divide the interview into two episodes`,explanationRu:`Интервью решено разделить на две части.`},{statement:`New episodes will be released every Thursday.`,answer:`false`,quote:`every other Thursday rather than weekly`,explanationRu:`Выпуски будут выходить через четверг, а не еженедельно.`},{statement:`The library charges for use of its meeting room.`,answer:`false`,quote:`its quiet meeting room for free`,explanationRu:`Библиотека предоставляет комнату бесплатно.`},{statement:`The team bought its microphones last year.`,answer:`not_stated`,quote:`we must bring our own microphones and laptop`,explanationRu:`Нужно принести свои микрофоны, но время и обстоятельства их покупки не сообщаются.`},{statement:`Permission is still needed for some photographs.`,answer:`true`,quote:`still need permission to use three archive photographs`,explanationRu:`Для трёх архивных фотографий разрешение ещё не получено.`}]}),c({slug:`climbing-final`,title:`Preparing for a climbing final`,topic:`sport`,cefr:`B1`,voices:[`male_3`,`female_2`],dialogue:[`The regional climbing final has moved from Saturday morning to Sunday afternoon because the sports centre is hosting a basketball match.`,`That gives me another day to recover. My shoulder feels better, but the coach says I should avoid difficult routes until Thursday.`,`Will you still train tonight? The team usually practises for two hours on Tuesdays.`,`I will join the warm-up and then spend forty minutes on balance exercises. I will not climb the overhanging wall this week.`,`Spectators need free tickets because the hall has limited space. My parents booked theirs yesterday.`,`Mine have not decided whether they can come. The final will be streamed online, although the organisers have not published the link yet.`],items:[{statement:`The climbing final will now take place on Sunday.`,answer:`true`,quote:`moved from Saturday morning to Sunday afternoon`,explanationRu:`Финал перенесли с субботы на воскресенье.`},{statement:`A football match caused the schedule change.`,answer:`false`,quote:`hosting a basketball match`,explanationRu:`Причиной стал баскетбольный, а не футбольный матч.`},{statement:`The athlete injured the shoulder during last month’s competition.`,answer:`not_stated`,quote:`My shoulder feels better`,explanationRu:`Травма плеча упомянута, но её время и обстоятельства не сообщаются.`},{statement:`The usual Tuesday practice lasts two hours.`,answer:`true`,quote:`usually practises for two hours on Tuesdays`,explanationRu:`Обычная тренировка во вторник длится два часа.`},{statement:`The athlete will use the overhanging wall this week.`,answer:`false`,quote:`I will not climb the overhanging wall this week`,explanationRu:`Спортсмен прямо отказывается от нависающей стены на этой неделе.`},{statement:`Spectator tickets cost nothing.`,answer:`true`,quote:`Spectators need free tickets`,explanationRu:`Билеты обязательны, но они бесплатные.`},{statement:`The streaming link is already available.`,answer:`false`,quote:`have not published the link yet`,explanationRu:`Ссылка на трансляцию пока не опубликована.`}]}),c({slug:`forest-bird-survey`,title:`A forest bird survey`,topic:`nature`,cefr:`B2`,voices:[`female_3`,`male_1`],dialogue:[`For Saturday’s bird survey, teams will follow three fixed routes through the forest and record every species they hear or see.`,`I assumed we would count individual birds, but identifying the same bird twice could make the numbers unreliable.`,`Exactly. Beginners record presence rather than exact numbers. Experienced leaders will estimate populations at selected points along each route.`,`The forecast mentions light rain. Does the survey continue in wet weather?`,`Light rain is acceptable, but strong wind makes birds difficult to hear. A cancellation message would be sent before six on Saturday morning.`,`I will charge my phone for the recording app. Paper forms are also available, and location services can be disabled after each observation is saved.`],items:[{statement:`Survey teams will use three predetermined routes.`,answer:`true`,quote:`three fixed routes through the forest`,explanationRu:`Команды идут по трём заранее установленным маршрутам.`},{statement:`Beginners must count every individual bird.`,answer:`false`,quote:`Beginners record presence rather than exact numbers`,explanationRu:`Новички отмечают наличие вида, а не точное число птиц.`},{statement:`Experienced leaders estimate populations at certain locations.`,answer:`true`,quote:`estimate populations at selected points`,explanationRu:`Руководители оценивают численность в выбранных точках.`},{statement:`Any amount of rain will cancel the survey.`,answer:`false`,quote:`Light rain is acceptable`,explanationRu:`Небольшой дождь допустим и не приводит к отмене.`},{statement:`Strong wind can make birds harder to hear.`,answer:`true`,quote:`strong wind makes birds difficult to hear`,explanationRu:`Сильный ветер мешает услышать птиц.`},{statement:`A cancellation message would be sent after six on Saturday morning.`,answer:`false`,quote:`before six on Saturday morning`,explanationRu:`Сообщение должны отправить до шести утра, а не после.`},{statement:`Every volunteer owns a smartphone.`,answer:`not_stated`,quote:`Paper forms are also available`,explanationRu:`Есть бумажные бланки, но наличие телефона у каждого не обсуждается.`}]}),c({slug:`shared-flat`,title:`Choosing a shared flat`,topic:`housing`,cefr:`B1`,voices:[`male_2`,`female_1`],dialogue:[`I viewed the flat near the university. The smaller bedroom is available from September, and the rent includes water but not electricity.`,`How long is the journey to campus? The advert says fifteen minutes, although it does not explain whether that is on foot.`,`It took me twelve minutes by bicycle. There is a locked storage area downstairs, so I would not need to keep my bike in the bedroom.`,`Who else lives there? I would prefer a quiet place because I study most evenings.`,`Two postgraduate students share the flat. They rarely have parties, but one of them practises the violin for an hour before dinner.`,`That should be fine. The landlord asks for a six-month contract and one month’s rent as a deposit. Pets are not permitted.`],items:[{statement:`The bedroom can be rented from September.`,answer:`true`,quote:`available from September`,explanationRu:`Комната освобождается с сентября.`},{statement:`Electricity is included in the monthly rent.`,answer:`false`,quote:`rent includes water but not electricity`,explanationRu:`Вода включена, а электричество оплачивается отдельно.`},{statement:`Cycling to the university took twelve minutes.`,answer:`true`,quote:`It took me twelve minutes by bicycle`,explanationRu:`Поездка на велосипеде заняла двенадцать минут.`},{statement:`The bicycle must be kept inside the bedroom.`,answer:`false`,quote:`a locked storage area downstairs`,explanationRu:`Для велосипеда есть закрытое место хранения внизу.`},{statement:`Three postgraduate students currently live in the flat.`,answer:`false`,quote:`Two postgraduate students share the flat`,explanationRu:`В квартире живут двое аспирантов, а не трое.`},{statement:`The violin is played after dinner.`,answer:`false`,quote:`practises the violin for an hour before dinner`,explanationRu:`На скрипке занимаются до ужина.`},{statement:`The deposit can be paid in two instalments.`,answer:`not_stated`,quote:`one month’s rent as a deposit`,explanationRu:`Размер залога известен, но способ оплаты частями не обсуждается.`}]}),c({slug:`surprise-party`,title:`Planning a surprise party`,topic:`relationships`,cefr:`B2`,voices:[`female_2`,`male_3`],dialogue:[`We need to change the surprise party plan. Eva’s train arrives at 5:15, nearly an hour earlier than she first told us.`,`Then inviting everyone for six is risky. Her sister can take her for coffee while we finish decorating the community room.`,`Good. I ordered a chocolate cake, but I have just learned that Eva has stopped eating dairy products.`,`The bakery can replace it with a vegan lemon cake at no extra cost if we confirm the change before noon tomorrow.`,`I will call them. We have twenty-two guests confirmed, including three children. Ben has not replied, so do not count him yet.`,`The room has a music system, but its speakers are quite weak. I can bring mine; we still have not agreed on a playlist.`],items:[{statement:`Eva’s train will arrive earlier than expected.`,answer:`true`,quote:`nearly an hour earlier than she first told us`,explanationRu:`Поезд прибывает почти на час раньше первоначального времени.`},{statement:`Eva’s sister will take her shopping.`,answer:`false`,quote:`Her sister can take her for coffee`,explanationRu:`Сестра поведёт Еву пить кофе, а не за покупками.`},{statement:`Eva currently avoids dairy products.`,answer:`true`,quote:`Eva has stopped eating dairy products`,explanationRu:`Ева перестала употреблять молочные продукты.`},{statement:`Changing the cake will cost more.`,answer:`false`,quote:`at no extra cost`,explanationRu:`Замена торта не требует дополнительной оплаты.`},{statement:`Twenty-two guests have confirmed attendance.`,answer:`true`,quote:`twenty-two guests confirmed`,explanationRu:`Подтверждение получено от двадцати двух гостей.`},{statement:`Ben will be travelling on the day of the party.`,answer:`not_stated`,quote:`Ben has not replied`,explanationRu:`Бен пока не ответил, а причина его молчания и планы на этот день неизвестны.`},{statement:`The final playlist has already been chosen.`,answer:`false`,quote:`we still have not agreed on a playlist`,explanationRu:`Список музыки пока не согласован.`}]}),c({slug:`school-fire-drill`,title:`Reviewing a school fire drill`,topic:`safety`,cefr:`B1`,voices:[`male_1`,`female_3`],dialogue:[`Yesterday’s fire drill took seven minutes, which is two minutes slower than our target. The upstairs classes left the building quickly.`,`The delay happened near the dining hall. Several students tried to use the main doors instead of the marked emergency exit.`,`We need clearer signs there. One exit light was not working, and the caretaker has already ordered a replacement.`,`Teachers counted their classes at the basketball court. Class 9B went to the front gate by mistake, so their teacher reported late.`,`Should we repeat the drill next week? Students might expect it and behave differently.`,`The head teacher wants another drill this term, but the date will remain secret. Staff will review the route maps on Monday.`],items:[{statement:`The drill met the school’s five-minute target.`,answer:`false`,quote:`took seven minutes, which is two minutes slower than our target`,explanationRu:`Эвакуация заняла семь минут вместо целевых пяти.`},{statement:`The upstairs classes evacuated quickly.`,answer:`true`,quote:`The upstairs classes left the building quickly`,explanationRu:`Скорость эвакуации верхних классов отмечена прямо.`},{statement:`Some students chose the wrong doors.`,answer:`true`,quote:`tried to use the main doors instead of the marked emergency exit`,explanationRu:`Часть учеников пошла к главным дверям вместо аварийного выхода.`},{statement:`Every exit light was working.`,answer:`false`,quote:`One exit light was not working`,explanationRu:`Один указатель выхода не работал.`},{statement:`Teachers checked attendance at the basketball court.`,answer:`true`,quote:`Teachers counted their classes at the basketball court`,explanationRu:`Перекличку проводили на баскетбольной площадке.`},{statement:`Class 9B went to the front gate.`,answer:`true`,quote:`Class 9B went to the front gate`,explanationRu:`Класс 9B по ошибке оказался у главных ворот.`},{statement:`The next drill will happen on Friday.`,answer:`not_stated`,quote:`the date will remain secret`,explanationRu:`Дата следующей тренировки скрыта, пятница не подтверждена.`}]}),c({slug:`bakery-delivery`,title:`Expanding a small bakery`,topic:`business`,cefr:`B2`,voices:[`female_1`,`male_2`],dialogue:[`Online orders now make up nearly a third of our bakery sales, but customers outside the town centre cannot currently request delivery.`,`Buying our own van would be expensive. A bicycle courier company has offered weekday delivery within eight kilometres for a fixed fee per order.`,`That would cover most nearby villages, though not Westford, which is eleven kilometres away. We could begin with a three-month trial.`,`The couriers collect at noon and four. Morning customers would receive bread the same afternoon, while late orders move to the next weekday.`,`We must redesign the boxes so cakes do not move on bicycles. The packaging supplier can send samples next week without charge.`,`Let us survey regular customers before signing. The courier says its riders are insured, but I want the policy details in writing.`],items:[{statement:`Online purchases represent almost one third of sales.`,answer:`true`,quote:`nearly a third of our bakery sales`,explanationRu:`Онлайн-заказы дают почти треть продаж.`},{statement:`The bakery has already bought a delivery van.`,answer:`false`,quote:`Buying our own van would be expensive`,explanationRu:`Покупку фургона только обсуждают и считают дорогой.`},{statement:`The courier offers deliveries seven days a week.`,answer:`false`,quote:`offered weekday delivery`,explanationRu:`Доставка предлагается по будням, не каждый день.`},{statement:`Westford is outside the proposed delivery area.`,answer:`true`,quote:`not Westford, which is eleven kilometres away`,explanationRu:`Уэстфорд дальше восьми километров и не входит в зону.`},{statement:`The proposed trial would last three months.`,answer:`true`,quote:`begin with a three-month trial`,explanationRu:`Пробный период рассчитан на три месяца.`},{statement:`Packaging samples will be supplied for free.`,answer:`true`,quote:`send samples next week without charge`,explanationRu:`Образцы упаковки отправят бесплатно.`},{statement:`Every regular customer supports the delivery plan.`,answer:`not_stated`,quote:`survey regular customers before signing`,explanationRu:`Опрос ещё не проведён, поэтому мнение всех клиентов неизвестно.`}]}),c({slug:`winter-light-festival`,title:`A winter light festival`,topic:`holidays`,cefr:`B1`,voices:[`male_3`,`female_2`],dialogue:[`The winter light festival begins on the first Friday in December. This year the displays will remain in the park for ten evenings.`,`Will the opening parade follow the usual route from the station? Road repairs have closed Market Street.`,`It will start at the library and finish beside the lake. The parade begins at half past six, thirty minutes later than last year.`,`Local schools are making lanterns, and the youth orchestra will perform near the lake. They need a covered stage in case it snows.`,`Food stalls must use reusable cups. Visitors can borrow one for a deposit and return it at any stall before leaving.`,`Entry to the park is free. The workshop tent charges for materials, but the programme has not listed the price yet.`],items:[{statement:`The festival displays will be open for ten evenings.`,answer:`true`,quote:`remain in the park for ten evenings`,explanationRu:`Световые объекты будут работать десять вечеров.`},{statement:`The parade will start at the railway station.`,answer:`false`,quote:`It will start at the library`,explanationRu:`В этом году шествие начинается у библиотеки.`},{statement:`The parade begins at 6:30 p.m.`,answer:`true`,quote:`begins at half past six`,explanationRu:`Half past six означает половину седьмого, то есть 18:30.`},{statement:`The youth orchestra will perform inside the library.`,answer:`false`,quote:`perform near the lake`,explanationRu:`Оркестр выступит у озера, а не в библиотеке.`},{statement:`Food stalls will use disposable cups.`,answer:`false`,quote:`Food stalls must use reusable cups`,explanationRu:`Требуются многоразовые, а не одноразовые стаканы.`},{statement:`Visitors have to pay to enter the park.`,answer:`false`,quote:`Entry to the park is free`,explanationRu:`Вход в парк бесплатный.`},{statement:`Workshop materials cost five pounds.`,answer:`not_stated`,quote:`the programme has not listed the price yet`,explanationRu:`Материалы платные, но точная цена ещё не указана.`}]})],d={id:`listening-pilot-v1`,revision:1,sets:l.concat(u,i)};t(d,{expectedCounts:{matching:20,true_false:20,interview:20},minimumTopics:20});var f=e(d),p=f.sets.filter(e=>e.type===`matching`),m=f.sets.filter(e=>e.type===`true_false`),h=f.sets.filter(e=>e.type===`interview`);export{h as LISTENING_INTERVIEW_SETS,p as LISTENING_MATCHING_SETS,f as LISTENING_PILOT_CATALOG,m as LISTENING_TRUE_FALSE_SETS};